(function(A){Object.assign(A.D,{"G568":{"l":"ἀπέχω","o":25,"ar":"<f><o>ἀπ-έχω</o>،</f> <s n=\"1.\">متعدٍّ، <s n=\"(a)\"><b>أمسك عن</b>، <b>أبعد</b>؛</s> <s n=\"(b)\"><b>نال كاملاً</b>، <b>استوفى</b>: مع المنصوب: <r v=\"Matt.6.2\"></r>، <r v=\"Matt.6.5\"></r>، <r v=\"Matt.6.16\"></r>، <r v=\"Luke.6.24\"></r>، <r v=\"Phil.4.18\"></r>، <r v=\"Phlm.1.15\"></r>؛ غير شخصي، <g>ἀπέχει</g>: <b>يكفي</b>: <r v=\"Mark.14.41\"></r>.</s> </s> <s n=\"2.\">لازم: <b>كان بعيدًا</b>، <b>على مسافة</b>: مطلقًا: <r v=\"Luke.15.20\"></r>؛ يليه <g>ἀπό</g>: <r v=\"Matt.14.24\"></r>، <r v=\"Matt.15.8\"></r>، <r v=\"Mark.7.6\"></r>، <r v=\"Luke.7.6\"></r>، <r v=\"Luke.15.20\"></r>، <r v=\"Luke.24.13\"></r>. الصيغة الوسطى: <b>امتنع عن</b>: مع المضاف إليه: <r v=\"Acts.15.29\"></r>، <r v=\"1Tim.4.3\"></r>، <r v=\"1Pet.2.11\"></r>؛ يليه <g>ἀπό</g>: <r v=\"Acts.15.20\"></r>، <r v=\"1Thess.4.3\"></r>، <r v=\"1Thess.5.22\"></r>.†</s>","en":"<f><o>ἀπ-έχω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7368\">רחק</h>;]</e> </et> <s n=\"1.\">trans., <s n=\"(a)\"><b>to hold back</b>, <b>keep off</b>;</s> <s n=\"(b)\"><b>to have in full</b>, <b>to have received</b> (on the \"punctiliar\" force of the compound, v. M, <i>Pr.</i>, 109, 247): c. acc., <r v=\"Matt.6.2\"></r>, <r v=\"Matt.6.5\"></r>, <r v=\"Matt.6.16\"></r>, <r v=\"Luke.6.24\"></r>, <r v=\"Phil.4.18\"></r>, <r v=\"Phlm.1.15\"></r> (for illustr. from <g>π.</g>, where it is used in receipts, v. Deiss., <i>BS</i>, 229; <i>LAE</i>, 110 f.; MM, s.v.); impers., <g>ἀπέχει</g> (Field, <i>Notes</i>, 39), <b>it is enough</b>: <r v=\"Mark.14.41\"></r>.</s> </s> <s n=\"2.\">Intrans., <b>to be away</b>, <b>distant</b>: absol., <r v=\"Luke.15.20\"></r>; seq. <g>ἀπό</g>, <r v=\"Matt.14.24\"></r> <r v=\"Matt.15.8\"></r>, <r v=\"Mark.7.6\"></r>, <r v=\"Luke.7.6\"></r> <r v=\"Luke.15.20\"></r> <r v=\"Luke.24.13\"></r>. Mid., <b>to abstain</b>: c. gen., <r v=\"Acts.15.29\"></r>, <r v=\"1Tim.4.3\"></r>, <r v=\"1Pet.2.11\"></r>; seq. <g>ἀπό</g>, <r v=\"Acts.15.20\"></r>, <r v=\"1Thess.4.3\"></r> <r v=\"1Thess.5.22\"></r>.†</s>"},"G537":{"l":"ἅπας","o":34,"ar":"<f><o>ἅπας</o>، <g>-ασα, -αν</g></f> <s><b>كل</b>، <b>الجميع (الكل)</b>، <b>جميعًا</b>: قبل الاسم مع أداة التعريف، كما في <r v=\"Luke.3.21\"></r>؛ أو بعده، كما في <r v=\"Mark.16.15\"></r>؛ مطلقًا، في المذكر، كما في <r v=\"Luke.5.26\"></r>؛ وفي المحايد، كما في <r v=\"Acts.2.44\"></r>؛ <g>ἅ. οὗτοι</g>، <r v=\"Acts.2.7\"></r>؛ <g>ἅ. ὑμεῖς</g>، <r v=\"Gal.3.28\"></r>. وأكثر ما ترد في لوقا وأعمال الرسل.</s>","en":"<f><o>ἅπας</o>, <g>-ασα, -αν</g></f> <et> <e t=\"derivation\">(strengthened form of <g>πᾶς</g>, v.s. <g>ἅ-</g>),</e> </et> <s><b>all</b>, <b>the whole</b>, <b>altogether</b>: bef. subst. with art., as <r v=\"Luke.3.21\"></r>; or after, as <r v=\"Mark.16.15\"></r>; absol., in masc., as <r v=\"Luke.5.26\"></r>; in neut., as <r v=\"Acts.2.44\"></r>; <g>ἅ. οὗτοι</g>, <r v=\"Acts.2.7\"></r> (LT); <g>ἅ. ὑμεῖς</g>, <r v=\"Gal.3.28\"></r> (TTr.). Most freq. in Lk, Ac (v. MM, <i>VG</i>, s.v.).</s>"},"G524":{"l":"ἀπαλγέω","o":1,"ar":"<f>* <o>ἀπ-αλγέω</o>، <g>-ῶ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: أصلاً، <b>يكفّ عن الشعور بالألم من أجل</b>.</s> <s n=\"2.\">في اليونانية المتأخرة <s n=\"(a)\"><b>ييأس</b>؛</s> <s n=\"(b)\"><b>يفقد الحسّ (يتبلّد)</b>، <b>يستهتر</b>: <r v=\"Eph.4.19\"></r>.†</s> </s>","en":"<f>* <o>ἀπ-αλγέω</o>, <g>-ῶ</g>,</f> <s n=\"1.\">prop., <b>to cease to feel pain for</b> (Thuc., ii, 61).</s> <s n=\"2.\">In late Gk. <s n=\"(a)\"><b>to despair</b> (Polyb., i, 35, 5);</s> <s n=\"(b)\"><b>to become callous</b>, <b>reckless</b> (Polyb., xvi, 12, 7; MM, <i>VGT</i>, s.v.): <r v=\"Eph.4.19\"></r>.†</s> </s>"},"G516":{"l":"ἀξίως","o":6,"ar":"<f>** <o>ἀξίως</o>،</f> ظرف <s><b>باستحقاق، كما يحق</b>: <r v=\"Rom.16.2\"></r>، <r v=\"Eph.4.1\"></r>، <r v=\"Phil.1.27\"></r>؛ مع المضاف إليه، <g>ἀ. τ. Κυρίου</g>، <r v=\"Col.1.10\"></r>؛ <g>τ. θεοῦ</g> <r v=\"1Thess.2.12\"></r>، <r v=\"3John.1.6\"></r>.†</s>","en":"<f>** <o>ἀξίως</o>,</f> adv. <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.7.15\"></r> <r v=\"Wis.16.1\"></r>, <r v=\"Sir.14.11\"></r>*;]</e> </et> <s><b>worthily</b>: <r v=\"Rom.16.2\"></r>, <r v=\"Eph.4.1\"></r>, <r v=\"Phil.1.27\"></r>; c. gen. (freq. in Inscr.; Deiss., <i>BS</i>, 248; MM, <i>VGT</i>, 51), <g>ἀ. τ. Κυρίου</g>, <r v=\"Col.1.10\"></r>; <g>τ. θεοῦ</g> <r v=\"1Thess.2.12\"></r>, <r v=\"3John.1.6\"></r>.†</s>"},"G575":{"l":"ἀπό","o":616,"ar":"<f><o>ἀπό</o>،</f> حرف جر مع المضاف إليه، <e t=\"septuagint\">[في السبعينية ترجمةً لـ <h n=\"H4480\">מִן</h>، <h n=\"H1119\">בְּ</h>، <h n=\"H3926\">לְ</h>؛]</e> <s><b>من</b> (أي من الخارج). <s n=\"1.\">عن الانفصال والانقطاع؛ <s n=\"(1)\">عن الحركة من مكان: <r v=\"Matt.5.29\"></r>، <r v=\"Matt.5.30\"></r> <r v=\"Matt.7.23\"></r>، <r v=\"Luke.5.2\"></r> <r v=\"Luke.22.41\"></r>، وفي مواضع أخرى؛</s> <s n=\"(2)\">بمعنى التبعيض، <r v=\"Matt.9.16\"></r> <r v=\"Matt.27.21\"></r>، <r v=\"John.21.10\"></r>، <r v=\"Acts.5.2\"></r>، وفي مواضع أخرى؛ وأيضًا بعد أفعال الأكل إلخ؛</s> <s n=\"(3)\">عن الإبعاد، بعد أفعال مثل <g>λούω</g>، <g>λύω</g>، <g>σώζω</g>، <g>παύω</g>، إلخ؛ <g>ἀνάθεμα ἀ.</g>، <r v=\"Rom.9.3\"></r>؛ <g>ἀποθνήσκειν ἀ.</g>، <r v=\"Col.2.20\"></r>؛ <g>σαλευθῆναι</g>، <r v=\"2Thess.2.2\"></r>، <g>καθαρός</g>، <g>-ίζειν</g>، <g>ἀ.</g>، <r v=\"Acts.20.26\"></r>، <r v=\"2Cor.7.1\"></r>، <r v=\"Heb.9.14\"></r>؛</s> <s n=\"(4)\">عن الموضع، <r v=\"Matt.23.34\"></r> <r v=\"Matt.24.31\"></r>، وفي مواضع أخرى؛ بعد <g>μακράν</g>، <r v=\"Matt.8.30\"></r>؛ مقدَّمًا قبل مقاييس المسافة، <r v=\"John.10.18\"></r> <r v=\"John.21.8\"></r>، <r v=\"Rev.14.20\"></r>؛</s> <s n=\"(5)\">عن الزمن، <g>ἀπὸ τ. ὥρας</g>، <g>ἡμέρας</g>، إلخ، <r v=\"Matt.9.22\"></r>، <r v=\"John.19.27\"></r>، <r v=\"Acts.20.18\"></r>، <r v=\"Phil.1.5\"></r>، وفي مواضع أخرى؛ <g>ἀπ’ αἰῶνος</g>، <r v=\"Luke.1.70\"></r>، وفي مواضع أخرى؛ <g>ἀπ’ ἀρχῆς</g>، إلخ، <r v=\"Matt.19.4\"></r>، <r v=\"Rom.1.20\"></r>؛ <g>ἀπὸ βρέφους</g>، <r v=\"2Tim.3.15\"></r>؛ <g>ἀφ’ ἧς</g>، <b>منذ</b>، <r v=\"Luke.7.45\"></r>، وفي مواضع أخرى؛ <g>ἀπὸ τ. νῦν</g>، <r v=\"Luke.1.48\"></r>، وفي مواضع أخرى؛ <g>ἀπὸ τότε</g>، <r v=\"Matt.4.17\"></r>، وفي مواضع أخرى؛ <g>ἀπὸ πέρυσι</g>، <b>منذ العام الماضي</b>، <r v=\"2Cor.8.10\"></r> <r v=\"2Cor.9.2\"></r>؛ <g>ἀπὸ πρωΐ</g>، <r v=\"Acts.28.23\"></r>؛</s> <s n=\"(6)\">عن الترتيب أو الرتبة، <g>ἀπὸ διετοῦς</g>، <r v=\"Matt.2.16\"></r>؛ <g>ἀπὸ Ἀβραάμ</g>، <r v=\"Matt.1.17\"></r>؛ <g>ἕβδομος ἀπὸ Ἀδάμ</g>، <r v=\"Jude.1.14\"></r>؛ <g>ἀπὸ μικροῦ ἕως μεγάλου</g>، <r v=\"Acts.8.10\"></r>، <r v=\"Heb.8.11\"></r>؛ <g>ἄρχεσθαι ἀπό</g>، <r v=\"Matt.20.8\"></r>، <r v=\"John.8.9\"></r>، <r v=\"Acts.8.35\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">عن الأصل؛ <s n=\"(1)\">عن المولد والنسب، ومن ثمّ عند الكُتّاب المتأخرين، <s n=\"(a)\">عن الأصل المكاني، <r v=\"Matt.21.11\"></r>، <r v=\"Mark.15.43\"></r>، <r v=\"John.1.45\"></r>، <r v=\"Acts.10.38\"></r>، وفي مواضع أخرى؛ <g>οἱ ἀπὸ Ἰταλίας</g>، <r v=\"Heb.13.24\"></r>؛</s> <s n=\"(b)\">عن العضوية في جماعة أو هيئة، <r v=\"Acts.12.1\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">عن المادة، <r v=\"Matt.3.4\"></r> <r v=\"Matt.27.21\"></r>؛</s> <s n=\"(d)\">بعد أفعال السؤال والطلب إلخ، <r v=\"Luke.11.50\"></r>، <r v=\"Luke.11.51\"></r>، <r v=\"1Thess.2.6\"></r>؛</s> </s> <s n=\"(2)\">عن السبب أو الأداة أو الوسيلة أو المناسبة (كثيرًا = <g>ὑπό</g>، <g>παρά</g>، وبعد أفعال التعلّم والسمع والمعرفة إلخ)، <r v=\"Matt.7.16\"></r> <r v=\"Matt.11.29\"></r>، <r v=\"Luke.22.45\"></r>، <r v=\"Acts.2.22\"></r> <r v=\"Acts.4.36\"></r> <r v=\"Acts.9.13\"></r> <r v=\"Acts.12.14\"></r>، <r v=\"1Cor.11.23\"></r>، <r v=\"Gal.3.2\"></r>، وفي مواضع أخرى؛ <g>ἀπὸ τ. ὄχλου</g>، <r v=\"Luke.19.3\"></r> (قارن <r v=\"John.21.6\"></r>، <r v=\"Acts.22.11\"></r>)؛ <g>ἀπὸ τ. φόβου</g>، <r v=\"Matt.14.26\"></r>، وفي مواضع أخرى (قارن <r v=\"Matt.10.28\"></r> <r v=\"Matt.13.44\"></r>).</s> </s> <s n=\"3.\">عبارات هلنستية جديرة بالملاحظة: <g>φοβεῖσθαι ἀπό</g>؛ <g>προσέχειν ἀπό</g>؛ <g>ἀπὸ νότου</g> (العبرية <h n=\"H5045\">מִנֶּגֶב</h>)، <r v=\"Rev.21.13\"></r>؛ <g>ἀπὸ προσώπου</g> (<h n=\"H6440\">מִפְּנֵי</h>)، <r v=\"2Thess.1.9\"></r>؛ <g>ἀπὸ τ. καρδιῶν</g> (<h n=\"H3820\">בְּלֵב</h>)، <r v=\"Matt.18.35\"></r>؛ <g>ἀπὸ ὁ ὤν</g>، <r v=\"Rev.1.4\"></r>.</s> <s n=\"4.\">في التركيب، تدل <g>ἀπό</g> على الانفصال والمغادرة والأصل إلخ (<g>ἀπολύω</g>، <g>ἀπέρχομαι</g>، <g>ἀπογράφω</g>)؛ ولها أيضًا قوة الإتمام، كما في <g>ἀφικνεῖσθαι</g>، <g>ἀφικνεῖσθαι</g>، انظره.</s> </s>","en":"<f><o>ἀπό</o> (on the freq. neglect of elision bef. vowels, v. Tdf., <i>Pr.</i>, 94, WH, <i>App.</i>, 146),</f> prep. c. gen. (WM, 462 ff.; on its relation to <g>ἐκ</g>, <g>παρά</g>, <g>ὑπό</g>, WM, 456 f.), <e t=\"septuagint\">[in LXX for <h n=\"H4480\">מִן</h>, <h n=\"H1119\">בְּ</h>, <h n=\"H3926\">לְ</h>;]</e> <s><b>from</b> (i.e. from the exterior). <s n=\"1.\">Of separation and cessation; <s n=\"(1)\">of motion from a place: <r v=\"Matt.5.29\"></r>, <r v=\"Matt.5.30\"></r> <r v=\"Matt.7.23\"></r>, <r v=\"Luke.5.2\"></r> <r v=\"Luke.22.41\"></r>, al.;</s> <s n=\"(2)\">in partitive sense (M, <i>Pr.</i>, 72, 102, 245; MM, s.v.; Bl., § 40, 2), <r v=\"Matt.9.16\"></r> <r v=\"Matt.27.21\"></r>, <r v=\"John.21.10\"></r>, <r v=\"Acts.5.2\"></r>, al.; also after verbs of eating, etc.;</s> <s n=\"(3)\">of alienation (cl. gen. of separation), after such verbs as <g>λούω</g> (Deiss., <i>BS</i>, 227), <g>λύω</g>, <g>σώζω</g>, <g>παύω</g>, etc.; <g>ἀνάθεμα ἀ.</g>, <r v=\"Rom.9.3\"></r>; <g>ἀποθνήσκειν ἀ.</g>, <r v=\"Col.2.20\"></r>; <g>σαλευθῆναι</g>, <r v=\"2Thess.2.2\"></r>, <g>καθαρός</g>, <g>-ίζειν</g>, <g>ἀ.</g> (Deiss., <i>BS</i>, 196, 216), <r v=\"Acts.20.26\"></r>, <r v=\"2Cor.7.1\"></r>, <r v=\"Heb.9.14\"></r>;</s> <s n=\"(4)\">of position, <r v=\"Matt.23.34\"></r> <r v=\"Matt.24.31\"></r>, al.; after <g>μακράν</g>, <r v=\"Matt.8.30\"></r>; transposed before measures of distance, <r v=\"John.10.18\"></r> <r v=\"John.21.8\"></r>, <r v=\"Rev.14.20\"></r> (Abbott, <i>JG</i>, 227);</s> <s n=\"(5)\">of time, <g>ἀπὸ τ. ὥρας</g>, <g>ἡμέρας</g>, etc., <r v=\"Matt.9.22\"></r>, <r v=\"John.19.27\"></r>, <r v=\"Acts.20.18\"></r>, <r v=\"Phil.1.5\"></r>, al.; <g>ἀπ’ αἰῶνος</g>, <r v=\"Luke.1.70\"></r>, al.; <g>ἀπ’ ἀρχῆς</g>, etc., <r v=\"Matt.19.4\"></r>, <r v=\"Rom.1.20\"></r>; <g>ἀπὸ βρέφους</g>, <r v=\"2Tim.3.15\"></r>; <g>ἀφ’ ἧς</g>, <b>since</b>, <r v=\"Luke.7.45\"></r>, al.; <g>ἀπὸ τ. νῦν</g>, <r v=\"Luke.1.48\"></r>, al.; <g>ἀπὸ τότε</g>, <r v=\"Matt.4.17\"></r>, al.; <g>ἀπὸ πέρυσι</g>, <b>a year ago</b>, <r v=\"2Cor.8.10\"></r> <r v=\"2Cor.9.2\"></r>; <g>ἀπὸ πρωΐ</g>, <r v=\"Acts.28.23\"></r>;</s> <s n=\"(6)\">of order or rank, <g>ἀπὸ διετοῦς</g>, <r v=\"Matt.2.16\"></r>; <g>ἀπὸ Ἀβραάμ</g>, <r v=\"Matt.1.17\"></r>; <g>ἕβδομος ἀπὸ Ἀδάμ</g>, <r v=\"Jude.1.14\"></r>; <g>ἀπὸ μικροῦ ἕως μεγάλου</g>, <r v=\"Acts.8.10\"></r>, <r v=\"Heb.8.11\"></r>; <g>ἄρχεσθαι ἀπό</g>, <r v=\"Matt.20.8\"></r>, <r v=\"John.8.9\"></r>, <r v=\"Acts.8.35\"></r>, al.</s> </s> <s n=\"2.\">Of origin; <s n=\"(1)\">of birth, extraction, and hence, in late writers, <s n=\"(a)\">of local extraction (cl. <g>ἐξ</g>; Abbott, <i>JG</i>, 227 ff.), <r v=\"Matt.21.11\"></r>, <r v=\"Mark.15.43\"></r>, <r v=\"John.1.45\"></r>, <r v=\"Acts.10.38\"></r>, al.; <g>οἱ ἀπὸ Ἰταλίας</g> (WM, § 66, 6; M, <i>Pr.</i>, 237; Westc, Rendall, in l.), <r v=\"Heb.13.24\"></r>;</s> <s n=\"(b)\">of membership in a community or society (Bl., § 40, 2), <r v=\"Acts.12.1\"></r>, al.;</s> <s n=\"(c)\">of material (= cl. gen.; Bl., § 40, 2; M, <i>Pr.</i>, 102), <r v=\"Matt.3.4\"></r> <r v=\"Matt.27.21\"></r>;</s> <s n=\"(d)\">after verbs of asking, seeking, etc., <r v=\"Luke.11.50\"></r>, <r v=\"Luke.11.51\"></r>, <r v=\"1Thess.2.6\"></r> (Milligan, in l.);</s> </s> <s n=\"(2)\">of the cause, instrument, means or occasion (freq. = <g>ὑπό</g>, <g>παρά</g>, and after verbs of learning, hearing, knowing, etc.; Bl., § 40, 3), <r v=\"Matt.7.16\"></r> <r v=\"Matt.11.29\"></r>, <r v=\"Luke.22.45\"></r>, <r v=\"Acts.2.22\"></r> <r v=\"Acts.4.36\"></r> <r v=\"Acts.9.13\"></r> <r v=\"Acts.12.14\"></r>, <r v=\"1Cor.11.23\"></r>, <r v=\"Gal.3.2\"></r>, al.; <g>ἀπὸ τ. ὄχλου</g>, <r v=\"Luke.19.3\"></r> (cf. <r v=\"John.21.6\"></r>, <r v=\"Acts.22.11\"></r>); <g>ἀπὸ τ. φόβου</g>, <r v=\"Matt.14.26\"></r>, al. (cf. <r v=\"Matt.10.28\"></r> <r v=\"Matt.13.44\"></r>).</s> </s> <s n=\"3.\">Noteworthy Hellenistic phrases: <g>φοβεῖσθαι ἀπό</g> (M, <i>Pr.</i>, 102, 107); <g>προσέχειν ἀπό</g> (M, <i>Pr.</i>, 102, 107; Milligan, <i>NTD</i>, 50); <g>ἀπὸ νότου</g> (Heb. <h n=\"H5045\">מִנֶּגֶב</h>), <r v=\"Rev.21.13\"></r>; <g>ἀπὸ προσώπου</g> (<h n=\"H6440\">מִפְּנֵי</h>), <r v=\"2Thess.1.9\"></r> (Bl., § 40, 9); <g>ἀπὸ τ. καρδιῶν</g> (<h n=\"H3820\">בְּלֵב</h>), <r v=\"Matt.18.35\"></r>; <g>ἀπὸ ὁ ὤν</g> (WM, § 10, 2; M, <i>Pr.</i>, 9), <r v=\"Rev.1.4\"></r>.</s> <s n=\"4.\">In composition, <g>ἀπό</g> denotes separation, departure, origin, etc. (<g>ἀπολύω</g>, <g>ἀπέρχομαι</g>, <g>ἀπογράφω</g>); it also has a perfective force (M, <i>Pr.</i>, 112, 247), as in <g>ἀφικνεῖσθαι</g>, <g>ἀφικνεῖσθαι</g>, q.v.</s> </s>"},"G538":{"l":"ἀπατάω","o":3,"ar":"<f><o>ἀπατάω</o>، <g>-ῶ</g></f> <s><b>يخدع</b>: مع المنصوب، <r v=\"Jas.1.26\"></r>؛ مع المنصوب للشخص والقابل للشيء، <r v=\"Eph.5.6\"></r>؛ المبني للمجهول، <r v=\"1Tim.2.14\"></r> (قارن <x><g>ἐξαπατάω</g></x>).†</s>","en":"<f><o>ἀπατάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπάτη</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6601\">פּתה</h>, <h n=\"H5377\">נשׁא</h> hi., etc.;]</e> </et> <s><b>to deceive</b>: c. acc., <r v=\"Jas.1.26\"></r>; c. acc. pers., dat. rei, <r v=\"Eph.5.6\"></r>; pass., <r v=\"1Tim.2.14\"></r> (on its infrequency in late writers, v. MM, <i>VGT</i>, s.v.; cf. <x><g>ἐξαπατάω</g></x>).†</s>"},"G543":{"l":"ἀπείθεια","o":7,"ar":"<f>** <o>ἀπείθεια</o></f> <s><b>عصيان</b>: <r v=\"Rom.11.30\"></r>، <r v=\"Rom.11.32\"></r>، <r v=\"Heb.4.6\"></r>، <r v=\"Heb.4.11\"></r>؛ <g>υἱοὶ τῆς ἀ.</g>، <r v=\"Eph.2.2\"></r> <r v=\"Eph.5.6\"></r>، <r v=\"Col.3.6\"></r>.†</s>","en":"<f>** <o>ἀπείθεια</o></f> <et> <e t=\"derivation\">(WH, <g>-θία</g>, exc. <r v=\"Heb.4.6\"></r>, <r v=\"Heb.4.11\"></r>), <g>-ας, ἡ</g> (&lt; <x><g>ἀπειθής</g></x>),</e> <e t=\"septuagint\">[in LXX <r v=\"4Macc.8.9\"></r>, <r v=\"4Macc.8.18\"></r> <r v=\"4Macc.12.4\"></r>*;]</e> </et> <s><b>disobedience</b> (MM, <i>VGT</i>, s.v.): <r v=\"Rom.11.30\"></r>, <r v=\"Rom.11.32\"></r>, <r v=\"Heb.4.6\"></r>, <r v=\"Heb.4.11\"></r>; <g>υἱοὶ τῆς ἀ.</g> (gen. of definition, v. M, <i>Pr.</i>, 73 f.), <r v=\"Eph.2.2\"></r> <r v=\"Eph.5.6\"></r>, <r v=\"Col.3.6\"></r> (T, WH, R, mg., omit).†</s>"},"G539":{"l":"ἀπάτη","o":7,"ar":"<f><o>ἀπάτη</o>، <g>-ης, ἡ</g>،</f> <s><b>خداع (غرور)</b>، <b>مكر</b>: <r v=\"Col.2.8\"></r>؛ <g>τοῦ πλούτου</g>، <r v=\"Matt.13.22\"></r>، <r v=\"Mark.4.19\"></r>؛ <g>τῆς ἀδικίας</g>، <r v=\"2Thess.2.10\"></r>؛ <g>τῆς ἁμαρτίας</g>، <r v=\"Heb.3.13\"></r>؛ <g>αἱ ἐπιθυμίαι τῆς ἀ.</g>، <r v=\"Eph.4.22\"></r>. جمع، <g>ἀπάται</g> (قارن <r v=\"2Thess.2.10\"></r>): <r v=\"2Pet.2.13\"></r> .†</s>","en":"<f><o>ἀπάτη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.9.6\"></r> <h>א</h> (no Heb. equiv.), <r v=\"Jdt.9.3\"></r>, <r v=\"Jdt.9.10\"></r>, <r v=\"Jdt.9.13\"></r> <r v=\"Jdt.16.8\"></r>, <r v=\"4Macc.18.8\"></r>*;]</e> </et> <s><b>deceit</b>, <b>deceitfulness</b>: <r v=\"Col.2.8\"></r>; <g>τοῦ πλούτου</g>, <r v=\"Matt.13.22\"></r>, <r v=\"Mark.4.19\"></r> (MM, <i>VGT</i>, s.v.); <g>τῆς ἀδικίας</g>, <r v=\"2Thess.2.10\"></r>; <g>τῆς ἁμαρτίας</g>, <r v=\"Heb.3.13\"></r>; <g>αἱ ἐπιθυμίαι τῆς ἀ.</g>, <r v=\"Eph.4.22\"></r>. pl., <g>ἀπάται</g> (v. M, <r v=\"2Thess.2.10\"></r>; <i>NTD</i>, 75; MM, <i>VGT</i>, s.v.): <r v=\"2Pet.2.13\"></r> (WH, mg., R., txt., <g>ἐν ἀγάπαις</g>).†</s>"},"G572":{"l":"ἀπλότης","o":8,"ar":"<f><o>ἀπλότης</o>، <g>-ητος, ή</g></f> <s><b>بساطة</b>، <b>إخلاص</b>: <r v=\"Rom.12.8\"></r>، <r v=\"2Cor.11.3\"></r>، <r v=\"Eph.6.5\"></r>، <r v=\"Col.3.22\"></r>؛ وكما تظهر في العطاء السخي غير الأناني، <b>سخاء</b>، <b>جود</b>: <r v=\"2Cor.8.2\"></r> <r v=\"2Cor.9.11\"></r>، <r v=\"2Cor.9.13\"></r> (قارن <r v=\"Rom.12.8\"></r>، <r v=\"Jas.1.5\"></r>؛ وانظر تحت مدخل <x><g>ἁπλῶς</g></x>).†</s>","en":"<f><o>ἀπλότης</o>, <g>-ητος, ή</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἁπλοῦς</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.15.11\"></r> (<h n=\"H8537\">תֹּם</h>), <r v=\"1Chr.29.17\"></r> (<h n=\"H3824\">לֵבָב</h> <h n=\"H3476\">ישֶׁר</h>, <g>ἁ. τῆς καρδίας</g>, cf. <r v=\"Col.3.22\"></r>, where v. Lft.), <r v=\"Wis.1.1\"></r>, al.;]</e> </et> <s><b>simplicity</b>, <b>sincerity</b>: <r v=\"Rom.12.8\"></r>, <r v=\"2Cor.11.3\"></r>, <r v=\"Eph.6.5\"></r>, <r v=\"Col.3.22\"></r>; as manifested in generous, unselfish giving, <b>liberality</b>, <b>graciousness</b>: <r v=\"2Cor.8.2\"></r> <r v=\"2Cor.9.11\"></r>, <r v=\"2Cor.9.13\"></r> (v. <i>ICC</i>, <r v=\"Rom.12.8\"></r>; Hort, <r v=\"Jas.1.5\"></r>, and v.s. <x><g>ἁπλῶς</g></x>).†</s>"},"G526":{"l":"ἀπαλλοτριόω","o":3,"ar":"<f><o>ἀπ-αλλοτριόω</o>، <g>-ῶ</g>،</f> <s><b>يُبعِد</b>، <b>يجعله غريبًا (أجنبيًا)</b>؛ المبني للمجهول: <r v=\"Eph.2.12\"></r> <r v=\"Eph.4.18\"></r>، <r v=\"Col.1.21\"></r> .† </s>","en":"<f><o>ἀπ-αλλοτριόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2114\">זוּר</h>, <h n=\"H5144\">נזר</h>, etc.;]</e> </et> <s><b>to alienate</b>, <b>estrange</b>; pass.: <r v=\"Eph.2.12\"></r> <r v=\"Eph.4.18\"></r>, <r v=\"Col.1.21\"></r> (MM, <i>VGT</i>, s.v.; Cremer, 95, 633).† </s>"},"G547":{"l":"ἀπειλή","o":3,"ar":"<f><o>ἀπειλή</o>، <g>-ῆ, ἡ</g>،</f> <s><b>تهديد</b>، <b>وعيد</b>: <r v=\"Acts.4.29\"></r> <r v=\"Acts.9.1\"></r>، <r v=\"Eph.6.9\"></r>.†</s>","en":"<f><o>ἀπειλή</o>, <g>-ῆ, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1606\">גְּעָרָה</h>, etc.;]</e> </et> <s><b>threatening</b>, <b>threat</b>: <r v=\"Acts.4.29\"></r> <r v=\"Acts.9.1\"></r>, <r v=\"Eph.6.9\"></r>.†</s>"},"G591":{"l":"ἀποδίδωμι","o":48,"ar":"<f><o>ἀπο-δίδωμι</o>،</f> <s><b>يسلِّم</b> أو <b>يُرجع</b>، <b>يردّ</b>، <b>يعيد</b>: <r v=\"Matt.27.58\"></r>، <r v=\"Luke.4.20\"></r> <r v=\"Luke.9.42\"></r> <r v=\"Luke.19.8\"></r>؛ خاصةً عن الأجور والديون والأقسام ونحوها، <b>يؤدّي</b> ما هو مستحق، <b>يوفي</b>: مطلقًا، <r v=\"Matt.18.25\"></r>، <r v=\"Matt.18.28\"></r>، <r v=\"Luke.7.42\"></r>. مع المنصوب، <r v=\"Matt.5.26\"></r> <r v=\"Matt.18.29\"></r>، <r v=\"Matt.18.30\"></r>، <r v=\"Matt.18.34\"></r> <r v=\"Matt.20.8\"></r> <r v=\"Matt.21.41\"></r> <r v=\"Matt.22.21\"></r>، <r v=\"Mark.12.17\"></r>، <r v=\"Luke.10.35\"></r> <r v=\"Luke.12.59\"></r> <r v=\"Luke.20.25\"></r>، <r v=\"Rom.13.7\"></r>، <r v=\"Heb.12.11\"></r>، <r v=\"Rev.22.2\"></r>؛ <g>ὅρκους</g>، <r v=\"Matt.5.33\"></r> (قارن <r v=\"Num.30.3\"></r>، <r v=\"Deut.23.21\"></r>، وفي مواضع أخرى)؛ عن الواجب الزوجي، <g>τ. ὀφειλήν</g>، <r v=\"1Cor.7.3\"></r>؛ <g>ἀμοιβάς</g>، <r v=\"1Tim.5.4\"></r>؛ <g>μαρτύριον</g>، <b>يؤدّي</b> (كواجب ملزم) <b>شهادة</b>، <r v=\"Acts.4.33\"></r>؛ <g>λόγον</g>، <b>يعطي حسابًا</b>، <r v=\"Matt.12.36\"></r>، <r v=\"Luke.16.2\"></r>، <r v=\"Acts.19.40\"></r>، <r v=\"Heb.13.17\"></r>، <r v=\"1Pet.4.5\"></r>؛ ومن ثَمَّ عن المجازاة والمكافأة، بالمعنى الحسن والسيئ، <r v=\"Matt.6.4\"></r>، <r v=\"Matt.6.6\"></r>، <r v=\"Matt.6.18\"></r> <r v=\"Matt.16.27\"></r>، <r v=\"Rom.2.6\"></r>، <r v=\"2Tim.4.8\"></r>، <r v=\"2Tim.4.14\"></r>، <r v=\"Rev.18.6\"></r> <r v=\"Rev.22.12\"></r>؛ <g>κακὸν ἀντὶ κακοῦ</g>، <r v=\"Rom.12.17\"></r>، <r v=\"1Thess.5.15\"></r>، <r v=\"1Pet.3.9\"></r>. الصيغة الوسطى، <b>يتخلّى عمّا يملكه</b>، ومن ثَمَّ <b>يبيع</b>: مع المنصوب للأشياء، <r v=\"Acts.5.8\"></r>، <r v=\"Heb.12.16\"></r>؛ مع المنصوب للأشخاص، <r v=\"Acts.7.9\"></r> (قارن <x><g>ἀντ-αποδίδωμι</g></x>).†</s>","en":"<f><o>ἀπο-δίδωμι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4376\">מכר</h>, <h n=\"H7725\">שׁוּב</h> hi., <h n=\"H5414\">נתן</h>, <h n=\"H8003\">שׁלם</h> pi., etc.;]</e> </et> <s><b>to give up</b> or <b>back</b>, <b>restore</b>, <b>return</b>: <r v=\"Matt.27.58\"></r>, <r v=\"Luke.4.20\"></r> <r v=\"Luke.9.42\"></r> <r v=\"Luke.19.8\"></r>; esp. of wages, debts, oaths, etc. (MM, s.v.), <b>to render</b> what is due, <b>to pay</b> (Deiss., <i>LAE</i>, 334 f.): absol., <r v=\"Matt.18.25\"></r>, <r v=\"Matt.18.28\"></r>, <r v=\"Luke.7.42\"></r>. c. acc., <r v=\"Matt.5.26\"></r> <r v=\"Matt.18.29\"></r>, <r v=\"Matt.18.30\"></r>, <r v=\"Matt.18.34\"></r> <r v=\"Matt.20.8\"></r> <r v=\"Matt.21.41\"></r> <r v=\"Matt.22.21\"></r>, <r v=\"Mark.12.17\"></r>, <r v=\"Luke.10.35\"></r> <r v=\"Luke.12.59\"></r> <r v=\"Luke.20.25\"></r>, <r v=\"Rom.13.7\"></r>, <r v=\"Heb.12.11\"></r>, <r v=\"Rev.22.2\"></r>; <g>ὅρκους</g>, <r v=\"Matt.5.33\"></r> (cf. <r v=\"Num.30.3\"></r>, <r v=\"Deut.23.21\"></r> al.); of conjugal duty, <g>τ. ὀφειλήν</g>, <r v=\"1Cor.7.3\"></r>; <g>ἀμοιβάς</g>, <r v=\"1Tim.5.4\"></r>; <g>μαρτύριον</g>, <b>to give</b> (as in duty bound) <b>testimony</b>, <r v=\"Acts.4.33\"></r>; <g>λόγον</g>, <b>to render account</b>, <r v=\"Matt.12.36\"></r>, <r v=\"Luke.16.2\"></r>, <r v=\"Acts.19.40\"></r>, <r v=\"Heb.13.17\"></r>, <r v=\"1Pet.4.5\"></r>; hence of requital, recompense, both in good and bad sense, <r v=\"Matt.6.4\"></r>, <r v=\"Matt.6.6\"></r>, <r v=\"Matt.6.18\"></r> <r v=\"Matt.16.27\"></r>, <r v=\"Rom.2.6\"></r>, <r v=\"2Tim.4.8\"></r>, <r v=\"2Tim.4.14\"></r>, <r v=\"Rev.18.6\"></r> <r v=\"Rev.22.12\"></r>; <g>κακὸν ἀντὶ κακοῦ</g>, <r v=\"Rom.12.17\"></r>, <r v=\"1Thess.5.15\"></r>, <r v=\"1Pet.3.9\"></r>. Mid., <b>to give up of one's own</b>, hence <b>to sell</b> (fr. Hdt. on): c. acc. rei, <r v=\"Acts.5.8\"></r>, <r v=\"Heb.12.16\"></r>; c. acc. pers., <r v=\"Acts.7.9\"></r> (cf. <x><g>ἀντ-αποδίδωμι</g></x>).†</s>"},"G515":{"l":"ἀξιόω","o":7,"ar":"<f><o>ἀξιόω</o>، <g>-ῶ</g></f> <s n=\"(a)\"><b>يحسبه مستحقًّا</b>: مع المنصوب والمصدر (قارن <x><g>κατ-αξιόω</g></x>)، <r v=\"Luke.7.7\"></r>؛ والمعنى نفسه مع المضاف إليه للأشياء، <r v=\"2Thess.1.11\"></r>؛ المبني للمجهول مع المضاف إليه للأشياء، <r v=\"1Tim.5.17\"></r>، <r v=\"Heb.3.3\"></r> <r v=\"Heb.10.29\"></r>؛</s> <s n=\"(b)\"><b>يستحسن، يرى من المناسب</b>: مع المصدر، <r v=\"Acts.15.38\"></r> <r v=\"Acts.28.22\"></r>.†</s>","en":"<f><o>ἀξιόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄξιος</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1156\">בּעא</h>, <h n=\"H1245\">בּקשׁ</h>; freq. in Wi, I, II Mac;]</e> </et> <s n=\"(a)\"><b>to deem worthy</b>: c. acc. et inf. (v. MM, <i>VGT</i>, s.v., and cf. <x><g>κατ-αξιόω</g></x>), <r v=\"Luke.7.7\"></r>; id. et gen. rei, <r v=\"2Thess.1.11\"></r>; pass. c. gen. rei, <r v=\"1Tim.5.17\"></r>, <r v=\"Heb.3.3\"></r> <r v=\"Heb.10.29\"></r>;</s> <s n=\"(b)\"><b>to think fit</b>: c. inf. (v. M, <i>Pr.</i>, 205), <r v=\"Acts.15.38\"></r> <r v=\"Acts.28.22\"></r>.†</s>"},"G532":{"l":"ἀπαρασκεύαστος","o":1,"ar":"<f>* <o>ἀ-παρα-σκεύαστος</o>، <g>-ον</g></f> <s><b>غير مستعد</b>: <r v=\"2Cor.9.4\"></r>.†</s>","en":"<f>* <o>ἀ-παρα-σκεύαστος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>παρασκευάζω</g></x>),</e> </et> <s><b>unprepared</b>: <r v=\"2Cor.9.4\"></r>.†</s>"},"G571":{"l":"ἄπιστος","o":23,"ar":"<f><o>ἄ-πιστος</o>، <g>-ον</g></f> <s n=\"(a)\">عن الأشياء: <b>لا يُصدَّق</b>: <r v=\"Acts.26.8\"></r>؛</s> <s n=\"(b)\">عن الأشخاص: <b>بلا إيمان</b> أو <b>ثقة</b>، <b>غير مؤمن</b>: <r v=\"Matt.17.17\"></r>، <r v=\"Mark.9.19\"></r>، <r v=\"Luke.9.41\"></r>، <r v=\"Luke.12.46\"></r>، <r v=\"John.20.27\"></r>، <r v=\"Titus.1.15\"></r>، <r v=\"Rev.21.8\"></r>؛ وتحديدًا عن غير المؤمنين في مقابل المسيحيين: <r v=\"1Cor.6.6\"></r>، <r v=\"1Cor.7.12-1Cor.7.15\"></r>، <r v=\"1Cor.10.27\"></r>، <r v=\"1Cor.14.22-1Cor.14.24\"></r>، <r v=\"2Cor.4.4\"></r>، <r v=\"2Cor.6.14\"></r>، <r v=\"2Cor.6.15\"></r>، <r v=\"1Tim.5.8\"></r>.†</s>","en":"<f><o>ἄ-πιστος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>πιστός</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.17.6\"></r> <r v=\"Prov.28.25\"></r>, <r v=\"Isa.17.10\"></r>*;]</e> </et> <s n=\"(a)\">of things, <b>incredible</b>: <r v=\"Acts.26.8\"></r>;</s> <s n=\"(b)\">of persons, <b>without faith</b> or <b>trust</b>, <b>unbelieving</b>: <r v=\"Matt.17.17\"></r>, <r v=\"Mark.9.19\"></r>, <r v=\"Luke.9.41\"></r> <r v=\"Luke.12.46\"></r>, <r v=\"John.20.27\"></r>, <r v=\"Titus.1.15\"></r>, <r v=\"Rev.21.8\"></r>; specif., of unbelievers as opp. to Christians: <r v=\"1Cor.6.6\"></r> <r v=\"1Cor.7.12-1Cor.7.15\"></r> <r v=\"1Cor.10.27\"></r> <r v=\"1Cor.14.22-1Cor.14.24\"></r>, <r v=\"2Cor.4.4\"></r> <r v=\"2Cor.6.14\"></r>, <r v=\"2Cor.6.15\"></r>, <r v=\"1Tim.5.8\"></r> (cf. Lft., <i>Notes</i>, 265; Cremer, 491).†</s>"},"G529":{"l":"ἀπάντησις","o":4,"ar":"<f><o>ἀπάντησις</o>، <g>-εως, ἡ</g></f> <s><b>لقاء</b>؛ <g>εἰς ἀ.</g>، مع المضاف إليه أو القابل: <b>لملاقاة</b>: <r v=\"Matt.25.6\"></r>، <r v=\"Matt.27.32\"></r>، <r v=\"Acts.28.15\"></r>، <r v=\"1Thess.4.17\"></r>.†</s>","en":"<f><o>ἀπάντησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπαντάω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7121\">לִקְרַאת</h>;]</e> </et> <s>usually with v.l., <g>ὑπ-</g>; <b>a meeting</b>; <g>εἰς ἀ.</g>, c. gen. or dat., <b>to meet</b>: <r v=\"Matt.25.6\"></r> <r v=\"Matt.27.32\"></r> (WH, txt., omits), <r v=\"Acts.28.15\"></r>, <r v=\"1Thess.4.17\"></r> (v. M, <i>Th.</i>, in l.; M, <i>Pr.</i>, 14, 242; MM, <i>VGT</i>, s.v.; Lft., <i>Notes</i>, 69).†</s>"},"G512":{"l":"ἀνωφελής","o":2,"ar":"<f><o>ἀν-ωφελής</o>، <g>-ές</g></f> <s><b>عديم النفع</b>: <r v=\"Titus.3.9\"></r>؛ المحايد اسمًا: <b>عدم النفع</b>: <r v=\"Heb.7.18\"></r>.†</s>","en":"<f><o>ἀν-ωφελής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(<g>ἀ-</g> neg., <x><g>ὄφελος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.44.10\"></r> (<h n=\"H3276\">הוֹעִיל</h> <h n=\"H1115\">בִּלְתִּי</h>), <r v=\"Jer.2.8\"></r> (<h n=\"H3276\">הוֹעִיל</h> <h n=\"H3808\">לֹא</h>), <r v=\"Prov.28.3\"></r>, <r v=\"Wis.1.11\"></r>*;]</e> </et> <s><b>unprofitable</b>: <r v=\"Titus.3.9\"></r>; neut. as subst., <b>unprofitableness</b>: <r v=\"Heb.7.18\"></r>.†</s>"},"G561":{"l":"ἀπέναντι","o":5,"ar":"<f>† <o>ἀπ-έναντι</o>،</f> ظرف مع المضاف إليه (في اليونانية المتأخرة، وشائع في السبعينية)؛ <s n=\"1.\"><b>مقابل، تجاه</b>: <r v=\"Matt.27.61\"></r>، <r v=\"Mark.12.41\"></r>.</s> <s n=\"2.\"><b>أمام</b>، <b>قدّام</b>، <b>في حضرة</b>: <r v=\"Matt.27.24\"></r>، <r v=\"Acts.3.16\"></r>، <r v=\"Rom.3.18\"></r>.</s> <s n=\"3.\"><b>ضد</b>، <b>خلافًا لـ</b>: <r v=\"Acts.17.7\"></r>.†</s>","en":"<f>† <o>ἀπ-έναντι</o>,</f> adv. c. gen. (Hellenistic, common in LXX); <s n=\"1.\"><b>over against</b> (MM, s.v.): <r v=\"Matt.27.61\"></r>, <r v=\"Mark.12.41\"></r>, WH, mg.</s> <s n=\"2.\"><b>before</b>, <b>in the presence of</b>: <r v=\"Matt.27.24\"></r> (WH, mg.), <r v=\"Acts.3.16\"></r>, <r v=\"Rom.3.18\"></r>.</s> <s n=\"3.\"><b>against</b>: <r v=\"Acts.17.7\"></r>.†</s>"},"G576":{"l":"ἀποβαίνω","o":4,"ar":"<f><o>ἀπο-βαίνω</o>،</f> <s><b>ينزل (من السفينة)</b>، <b>يخرج إلى البر</b>: <r v=\"Luke.5.2\"></r>، <r v=\"John.21.9\"></r>؛ مجازيًا، عن الأحداث: <b>يؤول</b>، <b>ينتهي إلى</b>: <r v=\"Luke.21.13\"></r>، <r v=\"Phil.1.19\"></r>.†</s>","en":"<f><o>ἀπο-βαίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1961\">היה</h>, etc.;]</e> </et> <s><b>to step off</b>, <b>disembark</b>: <r v=\"Luke.5.2\"></r>, <r v=\"John.21.9\"></r>; metaph., of events, <b>to issue</b>, <b>turn out</b> (Field, <i>Notes</i>, 74): <r v=\"Luke.21.13\"></r>, <r v=\"Phil.1.19\"></r> (MM, s.v.).†</s>"},"G505":{"l":"ἀνυπόκριτος","o":6,"ar":"<f>** <o>ἀν-υπόκριτος</o>، <g>-ον</g></f> <s><b>بلا رياء</b>، <b>عديم الرياء</b>: <r v=\"Rom.12.9\"></r>، <r v=\"2Cor.6.6\"></r>، <r v=\"1Tim.1.5\"></r>، <r v=\"2Tim.1.5\"></r>، <r v=\"Jas.3.17\"></r>، <r v=\"1Pet.1.22\"></r>.†</s>","en":"<f>** <o>ἀν-υπόκριτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>ὑποκρίνομαι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.5.18\"></r> <r v=\"Wis.18.16\"></r>*;]</e> </et> <s><b>unfeigned</b>: <r v=\"Rom.12.9\"></r>, <r v=\"2Cor.6.6\"></r>, <r v=\"1Tim.1.5\"></r>, <r v=\"2Tim.1.5\"></r>, <r v=\"Jas.3.17\"></r>, <r v=\"1Pet.1.22\"></r> (Cremer, 380; MM, <i>VGT</i>, s.v.).†</s>"},"G579":{"l":"ἀπόβλητος","o":1,"ar":"<f>** <o>ἀπό-βλητος</o>، <g>-ον</g></f> <s><b>ما يُطرَح</b>، <b>مرفوض</b>: <r v=\"1Tim.4.4\"></r>.†</s>","en":"<f>** <o>ἀπό-βλητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποβάλλω</g></x>),</e> <e t=\"septuagint\">[in Aq.: <r v=\"Lev.7.18\"></r>, al.; Sm.: <r v=\"Hos.9.3\"></r> (<h n=\"H2931\">טמא</h>);]</e> </et> <s><b>to be thrown away</b>, <b>rejected</b>: <r v=\"1Tim.4.4\"></r> (Hom., Plut.).†</s>"},"G521":{"l":"ἀπαίδευτος","o":1,"ar":"<f><o>ἀ-παίδευτος</o>، <g>-ον</g></f> <s><b>غير متعلّم</b>، <b>جاهل، سخيف</b>: <r v=\"2Tim.2.23\"></r>.†</s>","en":"<f><o>ἀ-παίδευτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>παιδεύω</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3685\">כְּסִיל</h>, etc., chiefly in Wi. lit.;]</e> </et> <s><b>uninstructed</b>, <b>ignorant</b>: <r v=\"2Tim.2.23\"></r>.†</s>"},"G514":{"l":"ἄξιος","o":41,"ar":"<f><o>ἄξιος</o>، <g>-α, -ον</g></f> <s n=\"(a)\"><b>ذو وزن</b>، <b>يساوي</b> (غالبًا مع المضاف إليه، قارن <r v=\"Prov.3.15\"></r>، <r v=\"Prov.8.11\"></r>)، يليه <g>πρός</g>: <r v=\"Rom.8.18\"></r>؛</s> <s n=\"(b)\"><b>لائق</b>، <b>مستحق</b>: مع المضاف إليه: <r v=\"Matt.3.8\"></r>، <r v=\"Luke.3.8\"></r>، <r v=\"Luke.23.41\"></r>، <r v=\"Acts.26.20\"></r>، <r v=\"1Cor.16.4\"></r>؛ مطلقًا: <r v=\"2Thess.1.3\"></r>؛</s> <s n=\"(c)\">عن الأشخاص: <b>مستحق، أهل</b>؛ <s n=\"α\">بالمعنى الحسن: مع مضاف إليه الشيء: <r v=\"Matt.10.10\"></r>، <r v=\"Luke.7.4\"></r>، <r v=\"Luke.10.7\"></r>، <r v=\"Acts.13.46\"></r>، <r v=\"1Tim.1.15\"></r>، <r v=\"1Tim.4.9\"></r>، <r v=\"1Tim.5.18\"></r>، <r v=\"1Tim.6.1\"></r>؛ مع مصدر الماضي البسيط: <r v=\"Luke.15.19\"></r>، <r v=\"Luke.15.21\"></r>، <r v=\"Acts.13.25\"></r>، <r v=\"Rev.4.11\"></r>، <r v=\"Rev.5.2\"></r>، <r v=\"Rev.5.4\"></r>، <r v=\"Rev.5.9\"></r>، <r v=\"Rev.5.12\"></r>؛ يليه <g>ἵνα</g>: <r v=\"John.1.27\"></r>؛ <g>ὅς</g>: <r v=\"Luke.7.4\"></r>؛ مطلقًا، مع فهم ما يستحقه ضمنًا: <r v=\"Matt.10.11\"></r>، <r v=\"Matt.10.13\"></r>، <r v=\"Matt.22.8\"></r>، <r v=\"Rev.3.4\"></r>؛ مع مضاف إليه الشخص: <r v=\"Matt.10.37\"></r>، <r v=\"Matt.10.38\"></r>، <r v=\"Heb.11.38\"></r>؛</s> <s n=\"β\">بالمعنى السيئ؛ مع مضاف إليه الشيء: <r v=\"Luke.12.48\"></r>، <r v=\"Luke.23.15\"></r>، <r v=\"Acts.23.29\"></r>، <r v=\"Acts.25.11\"></r>، <r v=\"Acts.25.25\"></r>، <r v=\"Acts.26.31\"></r>، <r v=\"Rom.1.32\"></r>؛ مطلقًا: <r v=\"Rev.16.6\"></r>.†</s> </s>","en":"<f><o>ἄξιος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄγω</g></x>, in sense, <i>to weigh</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1121\">בֵּן</h> (<r v=\"Deut.25.2\"></r>), <h n=\"H4392\">מָלֵא</h>, <h n=\"H7737\">שָׁוָה</h>; freq. in Wis, II Mac;]</e> </et> <s n=\"(a)\"><b>of weight</b>, <b>worth</b> (often c. gen., cf. <r v=\"Prov.3.15\"></r> <r v=\"Prov.8.11\"></r>), seq. <g>πρός</g>: <r v=\"Rom.8.18\"></r> (v. Field, <i>Notes</i>, 157);</s> <s n=\"(b)\"><b>befitting</b>, <b>meet</b>: c. gen., <r v=\"Matt.3.8\"></r>, <r v=\"Luke.3.8\"></r> <r v=\"Luke.23.41\"></r>, <r v=\"Acts.26.20\"></r>, <r v=\"1Cor.16.4\"></r> (v. M, <i>Pr.</i>, 216); absol., <r v=\"2Thess.1.3\"></r>;</s> <s n=\"(c)\">of persons, <b>worthy</b>; <s n=\"α\">in good sense: c. gen. rei, <r v=\"Matt.10.10\"></r>, <r v=\"Luke.7.4\"></r> <r v=\"Luke.10.7\"></r>, <r v=\"Acts.13.46\"></r>, <r v=\"1Tim.1.15\"></r> <r v=\"1Tim.4.9\"></r> <r v=\"1Tim.5.18\"></r> <r v=\"1Tim.6.1\"></r>; c. aor. inf. (v. M, <i>Pr.</i>, 203): <r v=\"Luke.15.19\"></r>, <r v=\"Luke.15.21\"></r>, <r v=\"Acts.13.25\"></r>, <r v=\"Rev.4.11\"></r> <r v=\"Rev.5.2\"></r>, <r v=\"Rev.5.4\"></r>, <r v=\"Rev.5.9\"></r>, <r v=\"Rev.5.12\"></r>; seq. <g>ἵνα</g>: <r v=\"John.1.27\"></r>; <g>ὅς</g>, <r v=\"Luke.7.4\"></r>; absol., but of what understood: <r v=\"Matt.10.11\"></r>, <r v=\"Matt.10.13\"></r> <r v=\"Matt.22.8\"></r>, <r v=\"Rev.3.4\"></r>; c. gen. pers., <r v=\"Matt.10.37\"></r>, <r v=\"Matt.10.38\"></r>, <r v=\"Heb.11.38\"></r>;</s> <s n=\"β\">in bad sense; c. gen. rei, <r v=\"Luke.12.48\"></r> <r v=\"Luke.23.15\"></r>, <r v=\"Acts.23.29\"></r> <r v=\"Acts.25.11\"></r>, <r v=\"Acts.25.25\"></r> <r v=\"Acts.26.31\"></r>, <r v=\"Rom.1.32\"></r>; absol., <r v=\"Rev.16.6\"></r> (MM, <i>VGT</i>, s.v.).†</s> </s>"},"G548":{"l":"ἄπειμι","o":8,"ar":"<f><o>ἄπ-ειμι</o></f> <s><b>كان غائبًا</b>: <r v=\"1Cor.5.3\"></r>، <r v=\"2Cor.10.1\"></r>، <r v=\"2Cor.10.11\"></r>، <r v=\"2Cor.13.2\"></r>، <r v=\"2Cor.13.10\"></r>، <r v=\"Phil.1.27\"></r>، <r v=\"Col.2.5\"></r>.†</s>","en":"<f><o>ἄπ-ειμι</o></f> <et> <e t=\"derivation\">(<x><g>εἰμί</g></x>, <l>sum</l>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3582\">כּחד</h> ni., <h n=\"H5080\">נדח</h> ni.;]</e> </et> <s><b>to be absent</b>: <r v=\"1Cor.5.3\"></r>, <r v=\"2Cor.10.1\"></r>, <r v=\"2Cor.10.11\"></r> <r v=\"2Cor.13.2\"></r>, <r v=\"2Cor.13.10\"></r>, <r v=\"Phil.1.27\"></r>, <r v=\"Col.2.5\"></r>.†</s>"},"G565":{"l":"ἀπέρχομαι","o":126,"ar":"<f><o>ἀπ-έρχομαι</o>،</f> <s n=\"1.\"><b>مضى</b>، <b>انصرف، ذهب</b> (وعند الكتّاب المتأخرين أيضًا بقوة «إتمامية»: <b>وصل</b> إلى مقصده، إذ يمتد المعنى إلى الغاية)؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.13.25\"></r>، وفي مواضع أخرى؛ اسم الفاعل <g>ἀπελθών</g> يُستعمل حشوًا مع أفعال أخرى كما في العبرية، <r v=\"Matt.13.28\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">مع ذكر مكان أو شخص: <g>εἰς</g>، <r v=\"Matt.14.15\"></r>؛ <g>ἐπί</g>، <r v=\"Luke.24.24\"></r>؛ <g>πρός</g>، <r v=\"Rev.10.9\"></r>؛ <g>ἀπό</g>، <r v=\"Luke.1.38\"></r>؛ <g>ἐξω</g>، <r v=\"Acts.4.15\"></r>؛ <g>ἐκεῖ</g>، <r v=\"Matt.2.22\"></r>.</s> </s> <s n=\"2.\">كما في السبعينية، يليه <g>ὀπίσω</g> مع المضاف إليه (العبرية <h n=\"H1980,H310\">הָלַךְ אַחֲרֵי</h>): <b>ذهب وراء</b>، <b>تبع</b>: <r v=\"Mark.1.20\"></r>، <r v=\"John.12.19\"></r>؛ مجازيًا، <r v=\"Mark.1.42\"></r>، <r v=\"Rev.21.1\"></r>.</s>","en":"<f><o>ἀπ-έρχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1980\">הלךְ</h>;]</e> </et> <s n=\"1.\"><b>to go away</b>, <b>depart</b> (also, in late writers, with \"perfective\" force, <b>to arrive</b> at a destination, the thought being carried on to the goal; M, <i>Pr.</i>, 111 f., 247; MM, s.v.); <s n=\"(a)\">absol.: <r v=\"Matt.13.25\"></r>, al.; ptcp., <g>ἀπελθών</g>, used pleonastically with other verbs as in Heb. (Dalman, <i>Words</i>, 21), <r v=\"Matt.13.28\"></r>, al.;</s> <s n=\"(b)\">with mention of place or person: <g>εἰς</g>, <r v=\"Matt.14.15\"></r>; <g>ἐπί</g>, <r v=\"Luke.24.24\"></r>; <g>πρός</g>, <r v=\"Rev.10.9\"></r>; <g>ἀπό</g>, <r v=\"Luke.1.38\"></r>; <g>ἐξω</g>, <r v=\"Acts.4.15\"></r>; <g>ἐκεῖ</g>, <r v=\"Matt.2.22\"></r>.</s> </s> <s n=\"2.\">As in LXX, seq. <g>ὀπίσω</g>, c. gen. (Heb. <h n=\"H1980,H310\">הָלַךְ אַחֲרֵי</h>), <b>to go after</b>, <b>follow</b>: <r v=\"Mark.1.20\"></r>, <r v=\"John.12.19\"></r>; metaph., <r v=\"Mark.1.42\"></r>, <r v=\"Rev.21.1\"></r>.</s>"},"G520":{"l":"ἀπάγω","o":16,"ar":"<f><o>ἀπ-άγω</o>،</f> <s><b>اقتاد، ساق بعيدًا</b>: <r v=\"Luke.13.15\"></r>، <r v=\"Acts.23.17\"></r>، <r v=\"Acts.24.7\"></r>، <r v=\"1Cor.12.2\"></r>؛ خاصةً عن الاقتياد إلى المحاكمة (وهو مصطلح قانوني بهذا المعنى في الأتيكية) وإلى السجن والموت: <r v=\"Matt.26.57\"></r>، <r v=\"Matt.27.2\"></r>، <r v=\"Matt.27.31\"></r>، <r v=\"Mark.14.44\"></r>، <r v=\"Mark.14.53\"></r>، <r v=\"Mark.15.16\"></r>، <r v=\"Luke.21.12\"></r>، <r v=\"Luke.22.66\"></r>، <r v=\"Luke.23.26\"></r>، <r v=\"Acts.12.19\"></r>؛ عن اتجاه الطريق (يؤدي إلى): <r v=\"Matt.7.13\"></r>، <r v=\"Matt.7.14\"></r> (قارن <x><g>συν-απ-άγω</g></x>).†</s>","en":"<f><o>ἀπ-άγω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5090\">נהג</h>, <h n=\"H1980\">הלךְ</h> hi., etc.;]</e> </et> <s><b>to lead away</b>: <r v=\"Luke.13.15\"></r>, <r v=\"Acts.23.17\"></r> <r v=\"Acts.24.7\"></r> (R, mg.), <r v=\"1Cor.12.2\"></r>; esp. of leading to trial (so as law term in Attic), prison and death (MM, <i>VGT</i>, s.v.): <r v=\"Matt.26.57\"></r> <r v=\"Matt.27.2\"></r>, <r v=\"Matt.27.31\"></r>, <r v=\"Mark.14.44\"></r>, <r v=\"Mark.14.53\"></r> <r v=\"Mark.15.16\"></r>, <r v=\"Luke.21.12\"></r> <r v=\"Luke.22.66\"></r> <r v=\"Luke.23.26\"></r>, <r v=\"Acts.12.19\"></r>; of the direction of a way: <r v=\"Matt.7.13\"></r>, <r v=\"Matt.7.14\"></r> (cf. <x><g>συν-απ-άγω</g></x>).†</s>"},"G569":{"l":"ἀπιστέω","o":8,"ar":"<f>** <o>ἀπιστέω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>لم يؤمن</b>، <b>كان غير أمين</b>: <r v=\"Mark.16.11\"></r>، <r v=\"Mark.16.16\"></r>، <r v=\"Luke.24.11\"></r>، <r v=\"Luke.24.41\"></r>، <r v=\"Acts.28.24\"></r>، <r v=\"1Pet.2.7\"></r>؛ وكذلك على الأرجح <r v=\"Rom.3.3\"></r>، <r v=\"2Tim.2.13\"></r>.</s> <s n=\"2.\">في اليونانية الكلاسيكية: = <x><g>ἀπειθέω</g></x> (عصى) (قارن بشأن هذا المعنى <r v=\"Rom.3.3\"></r>، <r v=\"2Tim.2.13\"></r>، <r v=\"Rom.3.3\"></r>).†</s>","en":"<f>** <o>ἀπιστέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄπιστος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.1.2\"></r> <r v=\"Wis.10.7\"></r> <r v=\"Wis.12.17\"></r> <r v=\"Wis.18.13\"></r>, <r v=\"Sir.1.27\"></r>, <r v=\"2Macc.8.13\"></r>*;]</e> </et> <s n=\"1.\"><b>to disbelieve</b>, <b>be faithless</b>: <r v=\"Mark.16.11\"></r>, <r v=\"Mark.16.16\"></r>, <r v=\"Luke.24.11\"></r>, <r v=\"Luke.24.41\"></r>, <r v=\"Acts.28.24\"></r>, <r v=\"1Pet.2.7\"></r>; so prob. also <r v=\"Rom.3.3\"></r>, <r v=\"2Tim.2.13\"></r> (<i>ICC</i>, <i>CGT</i>, in ll.; MM, s.v.).</s> <s n=\"2.\">= <x><g>ἀπειθέω</g></x> (Hdt.; on this sense in <r v=\"Rom.3.3\"></r>, <r v=\"2Tim.2.13\"></r>, v. Vaughan on <r v=\"Rom.3.3\"></r>; Lft., <i>Notes</i>, 265; Thayer, s.v.).†</s>"},"G584":{"l":"ἀποδείκνυμι","o":4,"ar":"<f><o>ἀπο-δείκνυμι</o>،</f> <s n=\"1.\"><b>أخرج إلى العلن</b>، <b>أظهر</b>، <b>عرض</b>: <r v=\"1Cor.4.9\"></r>.</s> <s n=\"2.\"><b>أعلن</b>، <b>بيّن</b>: <r v=\"Acts.2.22\"></r>.</s> <s n=\"3.\"><b>برهن</b>: <r v=\"Acts.25.7\"></r>.</s> <s n=\"4.\">وكما هو شائع في اليونانية المتأخرة: <b>نادى بأحد</b> لمنصب: يليه <g>ὅτι</g>، <r v=\"2Thess.2.4\"></r>.†</s>","en":"<f><o>ἀπο-δείκνυμι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.2.9\"></r> (<h n=\"H7200\">ראה</h>), al.;]</e> </et> <s n=\"1.\"><b>to bring out</b>, <b>show forth</b>, <b>exhibit</b> (Lft., <i>Notes</i>, 200; <i>ICC</i>, in l.): <r v=\"1Cor.4.9\"></r>.</s> <s n=\"2.\"><b>to declare</b>, <b>show</b>: <r v=\"Acts.2.22\"></r>.</s> <s n=\"3.\"><b>to prove</b>: <r v=\"Acts.25.7\"></r>.</s> <s n=\"4.\">As freq. in late Gk., <b>to proclaim</b> to an office: seq. <g>ὅτι</g>, <r v=\"2Thess.2.4\"></r> (Milligan, in l.; MM, s.v.; Lft., <i>Notes</i>. 113.)†</s>"},"G507":{"l":"ἄνω","o":9,"ar":"<f><o>ἄνω</o>،</f> ظرف <s n=\"(a)\"><b>فوق</b>، <b>إلى فوق</b>: <r v=\"John.11.41\"></r>، <r v=\"Heb.12.15\"></r>؛</s> <s n=\"(b)\"><b>في الأعلى، من فوق</b> (عكس <x><g>κάτω</g></x>): <r v=\"Acts.2.19\"></r>؛ مع أداة التعريف <g>ἡ</g>، <r v=\"Gal.4.26\"></r>، <r v=\"Phil.3.14\"></r>؛ <g>τά</g>، <r v=\"John.8.23\"></r>، <r v=\"Col.3.1\"></r>، <r v=\"Col.3.2\"></r>؛ <g>ἕως ἄ.</g> (<i>إلى الحافة، إلى فوق</i>)، <r v=\"John.2.7\"></r>.†</s>","en":"<f><o>ἄνω</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <x><g>ἀνά</g></x>),</e> </et> <s n=\"(a)\"><b>up</b>, <b>upwards</b>: <r v=\"John.11.41\"></r>, <r v=\"Heb.12.15\"></r>;</s> <s n=\"(b)\"><b>above</b> (opp. to <x><g>κάτω</g></x>): <r v=\"Acts.2.19\"></r>; with art. <g>ἡ</g>, <r v=\"Gal.4.26\"></r>, <r v=\"Phil.3.14\"></r>; <g>τά</g>, <r v=\"John.8.23\"></r>, <r v=\"Col.3.1\"></r>, <r v=\"Col.3.2\"></r>; <g>ἕως ἄ.</g> (<i>up to the brim</i>), <r v=\"John.2.7\"></r> (Cremer, 106; MM, <i>VGT</i>, s.v.).†</s>"},"G562":{"l":"ἀπέραντος","o":1,"ar":"<f><o>ἀπέραντος</o>، <g>-ον</g></f> <s><b>لا نهاية له</b>، <b>لا ينتهي</b>: <r v=\"1Tim.1.4\"></r>.†</s>","en":"<f><o>ἀπέραντος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>περαίνω</g></x>, <i>to complete</i>, <i>finish</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.36.26\"></r> (<h n=\"H2714\">חֵקֶר</h> <h n=\"H369\">אֵין</h>), <r v=\"3Macc.2.9\"></r>*;]</e> </et> <s><b>endless</b>, <b>interminable</b>: <r v=\"1Tim.1.4\"></r>.†</s>"},"G509":{"l":"ἄνωθεν","o":13,"ar":"<f><o>ἄνωθεν</o></f> ظرف، <s n=\"(a)\"><b>من فوق</b>: <g>ἀπὸ ἄ.</g>، <r v=\"Matt.27.51\"></r>، <r v=\"Mark.15.38\"></r>؛ <g>ἐκ τῶν ἄ.</g>، <r v=\"John.19.28\"></r>؛ بمعنى من السماء: <r v=\"John.3.31\"></r> <r v=\"John.19.11\"></r>، <r v=\"Jas.1.17\"></r> <r v=\"Jas.3.15\"></r>، <r v=\"Jas.3.17\"></r> .</s> <s n=\"(b)\"><b>من الأول</b>، <b>من البداية</b>: <r v=\"Luke.1.3\"></r>، <r v=\"Acts.26.5\"></r>؛ ومن ثم</s> <s n=\"(c)\"><b>من جديد</b>، <b>ثانيةً</b>: <r v=\"John.3.3\"></r>، <r v=\"John.3.7\"></r>، (هكذا عند أكثر المفسرين)؛ <g>πάλιν ἄ.</g>، <r v=\"Gal.4.9\"></r>.†</s>","en":"<f><o>ἄνωθεν</o></f> adv, <et> <e t=\"derivation\">(&lt; <x><g>ἄνω</g></x>),</e> </et> <s n=\"(a)\"><b>from above</b>: <g>ἀπὸ ἄ.</g>, <r v=\"Matt.27.51\"></r>, <r v=\"Mark.15.38\"></r>; <g>ἐκ τῶν ἄ.</g>, <r v=\"John.19.28\"></r>; meaning, from heaven: <r v=\"John.3.31\"></r> <r v=\"John.19.11\"></r>, <r v=\"Jas.1.17\"></r> <r v=\"Jas.3.15\"></r>, <r v=\"Jas.3.17\"></r> .</s> <s n=\"(b)\"><b>from the first</b>, <b>from the beginning</b>: <r v=\"Luke.1.3\"></r>, <r v=\"Acts.26.5\"></r>; whence</s> <s n=\"(c)\"><b>anew</b>, <b>again</b>: <r v=\"John.3.3\"></r>, <r v=\"John.3.7\"></r>, (so most, but v. Meyer, in l.; cf. Field, <i>Notes</i>, 86 f.); <g>πάλιν ἄ.</g>, <r v=\"Gal.4.9\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G518":{"l":"ἀπαγγέλλω","o":45,"ar":"<f><o>ἀπ-αγγέλλω</o>،</f> <s>عن الرسول أو المتكلم أو الكاتب: <b>أخبر</b>، <b>أعلن</b>، <b>بلّغ</b>: مع المنصوب للشيء، <r v=\"Acts.4.23\"></r>، وفي مواضع أخرى؛ مع القابل للشخص، <r v=\"Matt.2.8\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.18.37\"></r>؛ <g>πῶς</g>، <r v=\"Luke.8.36\"></r>؛ <g>περί</g>، <r v=\"Luke.7.18\"></r> <r v=\"Luke.13.1\"></r>، <r v=\"Acts.28.21\"></r>، <r v=\"1Thess.1.9\"></r>؛ <g>λέγων</g>، <r v=\"Acts.22.26\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.12.14\"></r>؛ يليه <g>εἰς</g>، <r v=\"Mark.5.14\"></r>، <r v=\"Luke.8.34\"></r>.</s>","en":"<f><o>ἀπ-αγγέλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5046\">נגד</h> hi.;]</e> </et> <s>of a messenger, speaker, or writer,<b> to report</b>, <b>announce</b>, <b>declare</b>: c. acc. rei, <r v=\"Acts.4.23\"></r>, al.; c. dat. pers., <r v=\"Matt.2.8\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.18.37\"></r>; <g>πῶς</g>, <r v=\"Luke.8.36\"></r>; <g>περί</g>, <r v=\"Luke.7.18\"></r> <r v=\"Luke.13.1\"></r>, <r v=\"Acts.28.21\"></r>, <r v=\"1Thess.1.9\"></r>; <g>λέγων</g>, <r v=\"Acts.22.26\"></r>; c. acc. et inf., <r v=\"Acts.12.14\"></r>; seq. <g>εἰς</g>, <r v=\"Mark.5.14\"></r>, <r v=\"Luke.8.34\"></r> (MM, <i>VGT</i>, s.v.; Cremer, 25).</s>"},"G554":{"l":"ἀπεκδύω","o":2,"ar":"<f>*† <o>ἀπ-εκ-δύω</o>،</f> <s><b>خلع</b> الثياب أو الأسلحة؛ الصيغة الوسطى، <b>خلع عن نفسه</b>: <r v=\"Col.3.9\"></r>؛ <b>جرّد</b>، <b>سلب</b> (الصيغة الوسطى بمعنى المبني للمعلوم)، <r v=\"Col.2.15\"></r>.†</s>","en":"<f>*† <o>ἀπ-εκ-δύω</o>,</f> <s><b>to strip off</b> clothes or arms; mid., <b>to strip off from oneself</b>: <r v=\"Col.3.9\"></r>; <b>to strip</b>, <b>despoil</b> (mid, for act., <i>ICC</i>, in l.; but cf. Lft., Ellic.), <r v=\"Col.2.15\"></r>.†</s>"},"G545":{"l":"ἀπειθής","o":6,"ar":"<f><o>ἀπειθής</o>، <g>-ές</g></f> <s><b>غير طائع، عاصٍ</b>: مطلقًا، <r v=\"Luke.1.17\"></r>، <r v=\"Titus.1.16\"></r> <r v=\"Titus.3.3\"></r>؛ مع القابل، <r v=\"Acts.26.19\"></r>، <r v=\"Rom.1.30\"></r>، <r v=\"2Tim.3.2\"></r>.†</s>","en":"<f><o>ἀπειθής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <x><g>πείθομαι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4759\">מרה</h>, <h n=\"H4806\">מְרִי</h>, <h n=\"H5637\">סרר</h>;]</e> </et> <s><b>disobedient</b>: absol., <r v=\"Luke.1.17\"></r>, <r v=\"Titus.1.16\"></r> <r v=\"Titus.3.3\"></r>; c. dat., <r v=\"Acts.26.19\"></r>, <r v=\"Rom.1.30\"></r>, <r v=\"2Tim.3.2\"></r>.†</s>"},"G550":{"l":"ἀπεῖπον","o":1,"ar":"<f><o>ἀπ-εῖπον</o>، الماضي البسيط الثاني، وليس له مضارع مستعمل </f> <s n=\"1.\"><b>يُعلن، يصرّح</b>.</s> <s n=\"2.\"><b>ينهى، يمنع</b> (<r v=\"1Kgs.11.2\"></r>).</s> <s n=\"3.\"><b>يرفض، يتبرّأ من، يترك</b>: الماضي البسيط الأول في الصيغة الوسطى، <r v=\"2Cor.4.2\"></r>.†</s>","en":"<f><o>ἀπ-εῖπον</o>, 2 aor. without present in use </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3988\">מָאַס</h>, <h n=\"H559\">אָמַר</h>, etc.;]</e> </et> <s n=\"1.\"><b>to tell out</b>.</s> <s n=\"2.\"><b>to forbid</b> (<r v=\"1Kgs.11.2\"></r>).</s> <s n=\"3.\"><b>to renounce</b>: 1 aor. mid. (WH, <i>App.</i>, 164; MM, <i>VGT</i>, s.v.), <r v=\"2Cor.4.2\"></r>.†</s>"},"G558":{"l":"ἀπελεύθερος","o":1,"ar":"<f>* <o>ἀπ-ελεύθερος</o>، <g>-ου, ὁ, ἡ</g>،</f> <s><b>مُعتَق، عبد محرَّر</b>: <g>τ. κυρίου</g> (عتيق الرب)، <r v=\"1Cor.7.22\"></r>.†</s>","en":"<f>* <o>ἀπ-ελεύθερος</o>, <g>-ου, ὁ, ἡ</g>,</f> <s><b>a freedman</b>: <g>τ. κυρίου</g> (MM, s.v.), <r v=\"1Cor.7.22\"></r>.†</s>"},"G559":{"l":"Ἀπελλῆς","o":1,"ar":"<f><o>Ἀπελλῆς</o>، <g>-οῦ</g>، المنصوب <g>-ῆν</g>، <g>ὁ</g>،</f> <s><b>أبلّس</b>: <r v=\"Rom.16.10\"></r>.†</s>","en":"<f><o>Ἀπελλῆς</o>, <g>-οῦ</g>, acc. <g>-ῆν</g> (MM, s.v.), <g>ὁ</g>,</f> <s><b>Apelles</b>: <r v=\"Rom.16.10\"></r>.†</s>"},"G580":{"l":"ἀποβολή","o":2,"ar":"<f>* <o>ἀπο-βολή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>طرح</b>، <b>رفض</b>: عكس <x><g>πρόσλημψις</g></x>، <r v=\"Rom.11.15\"></r>.</s> <s n=\"2.\"><b>فقدان</b>، <b>خسارة</b>: <r v=\"Acts.27.22\"></r>.†</s>","en":"<f>* <o>ἀπο-βολή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποβάλλω</g></x>);</e> </et> <s n=\"1.\"><b>a throwing away</b>, <b>rejection</b>: opp. to <x><g>πρόσλημψις</g></x>, <r v=\"Rom.11.15\"></r>.</s> <s n=\"2.\"><b>a losing</b>, <b>loss</b>: <r v=\"Acts.27.22\"></r>.†</s>"},"G553":{"l":"ἀπεκδέχομαι","o":8,"ar":"<f>*† <o>ἀπ-εκ-δέχομαι</o>، فعل لازم الصيغة الوسطى،</f> <s><b>ينتظر</b> أو <b>يتوقّع بشوق</b>: مطلقًا، <r v=\"1Pet.3.20\"></r>؛ مع المنصوب للشيء، <r v=\"Rom.8.19\"></r>، <r v=\"Rom.8.23\"></r>، <r v=\"Rom.8.25\"></r>، <r v=\"1Cor.1.7\"></r>، <r v=\"Gal.5.5\"></r>؛ مع المنصوب للشخص، <r v=\"Phil.3.20\"></r>، <r v=\"Heb.9.28\"></r>.†</s>","en":"<f>*† <o>ἀπ-εκ-δέχομαι</o>, depon.,</f> <s><b>to await</b> or <b>expect eagerly</b> (Lft., <i>Notes</i>, 149; MM, <i>VGT</i>, s.v.): absol., <r v=\"1Pet.3.20\"></r>; c. acc. rei, <r v=\"Rom.8.19\"></r>, <r v=\"Rom.8.23\"></r>, <r v=\"Rom.8.25\"></r>, <r v=\"1Cor.1.7\"></r>, <r v=\"Gal.5.5\"></r>; c. acc. pers., <r v=\"Phil.3.20\"></r>, <r v=\"Heb.9.28\"></r>.†</s>"},"G563":{"l":"ἀπερισπάστως","o":1,"ar":"<f>*† <o>ἀπερισπάστως</o>،</f> ظرف <s><b>بدون ارتباك (تشتّت)</b>: <r v=\"1Cor.7.35\"></r>.†</s>","en":"<f>*† <o>ἀπερισπάστως</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <x><g>περισπάω</g></x>; the adj. occurs in <r v=\"Wis.16.11\"></r> <r v=\"Sir.41.1\"></r>);</e> </et> <s><b>without distraction</b>: <r v=\"1Cor.7.35\"></r>.†</s>"},"G544":{"l":"ἀπειθέω","o":14,"ar":"<f><o>ἀπειθέω</o>، <g>-ῶ</g></f> <s><b>عصى</b>، <b>لم يُطِع</b>، <b>كان غير مطيع</b>: مطلقًا: <r v=\"Acts.14.2\"></r>، <r v=\"Acts.19.9\"></r>، <r v=\"Rom.10.21\"></r>، <r v=\"Rom.11.31\"></r>، <r v=\"Rom.15.31\"></r>، <r v=\"Heb.3.18\"></r>، <r v=\"Heb.11.31\"></r>، <r v=\"1Pet.3.20\"></r>؛ مع القابل: <r v=\"John.3.36\"></r>، <r v=\"Rom.2.8\"></r>، <r v=\"Rom.11.30\"></r>، <r v=\"1Pet.2.8\"></r>، <r v=\"1Pet.3.1\"></r>، <r v=\"1Pet.4.17\"></r>.†</s>","en":"<f><o>ἀπειθέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπειθής</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4784\">מרה</h>, <h n=\"H5637\">סרר</h>, etc.;]</e> </et> <s>as in cl. (MM, <i>VGT</i>, s.v.); <b>to disobey</b>, <b>be disobedient</b>: absol., <r v=\"Acts.14.2\"></r> <r v=\"Acts.19.9\"></r>, <r v=\"Rom.10.21\"></r> <r v=\"Rom.11.31\"></r> <r v=\"Rom.15.31\"></r>, <r v=\"Heb.3.18\"></r> <r v=\"Heb.11.31\"></r>, <r v=\"1Pet.3.20\"></r>; c. dat., <r v=\"John.3.36\"></r>, <r v=\"Rom.2.8\"></r> <r v=\"Rom.11.30\"></r>, <r v=\"1Pet.2.8\"></r> <r v=\"1Pet.3.1\"></r> <r v=\"1Pet.4.17\"></r> (Cremer, 475).†</s>"},"G517":{"l":"ἀόρατος","o":5,"ar":"<f><o>ἀόρατος</o>، <g>-ον</g></f> <s><b>غير مرئي</b>، <b>لا يُرى</b>: <r v=\"Rom.1.20\"></r>، <r v=\"Col.1.15\"></r>، <r v=\"Col.1.16\"></r>، <r v=\"1Tim.1.17\"></r>، <r v=\"Heb.11.27\"></r>.†</s>","en":"<f><o>ἀόρατος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ὁράω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.1.2\"></r> (<h n=\"H8414\">תֹּהוּ</h>), <r v=\"Isa.45.3\"></r> (<h n=\"H4565\">מִסְתָּר</h>), <r v=\"2Macc.9.5\"></r>*;]</e> </et> <s><b>unseen</b>, <b>invisible</b>: <r v=\"Rom.1.20\"></r>, <r v=\"Col.1.15\"></r>, <r v=\"Col.1.16\"></r>, <r v=\"1Tim.1.17\"></r>, <r v=\"Heb.11.27\"></r>.†</s>"},"G570":{"l":"ἀπιστία","o":11,"ar":"<f>** <o>ἀπιστία</o>، <g>-ας, ἡ</g></f> <s><b>قلة الإيمان</b>، <b>عدم الإيمان</b>: <r v=\"Matt.13.58\"></r>، <r v=\"Mark.6.6\"></r> <r v=\"Mark.9.24\"></r> <r v=\"Mark.16.14\"></r>، <r v=\"Rom.3.3\"></r> (ولكن انظر تحت مدخل <x><g>ἀπιστέω</g></x>) <r v=\"Rom.4.20\"></r> <r v=\"Rom.11.20\"></r>، <r v=\"Rom.11.23\"></r>، <r v=\"1Tim.1.13\"></r>، <r v=\"Heb.3.12\"></r>، <r v=\"Heb.3.19\"></r>.†</s>","en":"<f>** <o>ἀπιστία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄπιστος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.14.25\"></r>, <r v=\"4Macc.12.4\"></r>*;]</e> </et> <s><b>want of faith</b>, <b>unbelief</b>: <r v=\"Matt.13.58\"></r>, <r v=\"Mark.6.6\"></r> <r v=\"Mark.9.24\"></r> <r v=\"Mark.16.14\"></r>, <r v=\"Rom.3.3\"></r> (but v.s. <x><g>ἀπιστέω</g></x>) <r v=\"Rom.4.20\"></r> <r v=\"Rom.11.20\"></r>, <r v=\"Rom.11.23\"></r>, <r v=\"1Tim.1.13\"></r>, <r v=\"Heb.3.12\"></r>, <r v=\"Heb.3.19\"></r> (<i>DCG</i>, ii, 775<i>a</i>; Cremer, 492).†</s>"},"G599":{"l":"ἀποθνῄσκω","o":111,"ar":"<f><o>ἀπο-θνῄσκω</o>،</f> <s><b>مات</b>: عن الموت الطبيعي: <r v=\"Mark.5.35\"></r>، وفي مواضع أخرى؛ عن الموت العنيف (بمعنى المبني للمجهول من <g>ἀποκτείνω</g>)، وخاصةً عن المسيح: <r v=\"Matt.26.35\"></r>، <r v=\"John.12.33\"></r>، <r v=\"Heb.10.28\"></r>، وفي مواضع أخرى؛ عن الموت الروحي: <r v=\"John.6.50\"></r>، <r v=\"Rom.8.13\"></r>، وفي مواضع أخرى؛ مع القابل بمعنى «بالنسبة إلى»: <r v=\"Rom.6.2\"></r>، <r v=\"Rom.6.10\"></r> <r v=\"Rom.14.7\"></r>، <r v=\"Rom.14.8\"></r>، <r v=\"Gal.2.19\"></r>؛ ومع المنصوب <g>ὅ</g>: <r v=\"Rom.6.10\"></r>؛ يليه <g>ἐν</g>: <r v=\"Matt.8.32\"></r>، <r v=\"John.8.21\"></r>، <r v=\"John.8.24\"></r>، <r v=\"1Cor.15.22\"></r>، <r v=\"Heb.11.37\"></r>، <r v=\"Rev.14.13\"></r>؛ يليه <g>ὑπέρ</g>، <g>περί</g>: <r v=\"John.11.50\"></r>، <r v=\"John.11.51\"></r> <r v=\"John.18.14\"></r>، <r v=\"Rom.5.6-Rom.5.8\"></r> <r v=\"Rom.14.15\"></r>، <r v=\"1Cor.15.3\"></r>، <r v=\"2Cor.5.15\"></r>، <r v=\"1Thess.5.10\"></r>، <r v=\"1Pet.3.18\"></r>؛ <g>ἀπό</g>: <r v=\"Col.2.20\"></r>؛ <g>ἐκ</g>: <r v=\"Rev.8.11\"></r>؛ مجازيًا: <r v=\"1Cor.15.31\"></r> (قارن <g>συν-αποθνήσκω</g>).</s>","en":"<f><o>ἀπο-θνῄσκω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4191\">מוּת</h>;]</e> </et> <s><b>to die</b>: of natural death, <r v=\"Mark.5.35\"></r>, al.; of violent death (pass. of <g>ἀποκτείνω</g>), esp. of Christ, <r v=\"Matt.26.35\"></r>, <r v=\"John.12.33\"></r>, <r v=\"Heb.10.28\"></r>, al.; of spiritual death, <r v=\"John.6.50\"></r>, <r v=\"Rom.8.13\"></r>, al.; c. dat. ref., <r v=\"Rom.6.2\"></r>, <r v=\"Rom.6.10\"></r> <r v=\"Rom.14.7\"></r>, <r v=\"Rom.14.8\"></r>, <r v=\"Gal.2.19\"></r>; acc., <g>ὅ</g>, <r v=\"Rom.6.10\"></r>; seq. <g>ἐν</g>, <r v=\"Matt.8.32\"></r>, <r v=\"John.8.21\"></r>, <r v=\"John.8.24\"></r>, <r v=\"1Cor.15.22\"></r>, <r v=\"Heb.11.37\"></r>, <r v=\"Rev.14.13\"></r>; seq. <g>ὑπέρ</g>, <g>περί</g>, <r v=\"John.11.50\"></r>, <r v=\"John.11.51\"></r> <r v=\"John.18.14\"></r>, <r v=\"Rom.5.6-Rom.5.8\"></r> <r v=\"Rom.14.15\"></r>, <r v=\"1Cor.15.3\"></r>, <r v=\"2Cor.5.15\"></r>, <r v=\"1Thess.5.10\"></r>, <r v=\"1Pet.3.18\"></r>; <g>ἀπό</g>, <r v=\"Col.2.20\"></r>; <g>ἐκ</g>, <r v=\"Rev.8.11\"></r>; fig., <r v=\"1Cor.15.31\"></r> (cf. <g>συν-αποθνήσκω</g>, and V. Milligan, <i>NTD</i>, 258 f.; <i>DCG</i>, i, 791<i>b</i>; Cremer, 286; MM, s.v.; on the perfective force of this verb, M, <i>Pr.</i>, 112, 114; and on the distinction bet. pres. and aor., M, <i>Pr.</i>, 113 f.).</s>"},"G530":{"l":"ἅπαξ","o":14,"ar":"<f><o>ἅπαξ</o>،</f> ظرف، <s n=\"(a)\"><b>مرة واحدة</b>: <r v=\"2Cor.11.25\"></r>، <r v=\"Heb.9.26\"></r>، <r v=\"Heb.9.27\"></r>؛ <g>ἔτι ἅ.</g>، <r v=\"Heb.12.26\"></r>، <r v=\"Heb.12.27\"></r>؛ <g>ἅ. τ. ἐνιαυτοῦ</g>، <r v=\"Heb.9.7\"></r>؛ <g>καί ἅ. κ. δίς</g>: <b>مرتين</b>: <r v=\"Phil.4.16\"></r>، <r v=\"1Thess.2.18\"></r>؛</s> <s n=\"(b)\"><b>مرة واحدة وإلى الأبد</b>: <r v=\"Heb.6.4\"></r> <r v=\"Heb.9.28\"></r> <r v=\"Heb.10.2\"></r>، <r v=\"1Pet.3.18\"></r>، <r v=\"Jude.1.3\"></r>، <r v=\"Jude.1.5\"></r>.†</s>","en":"<f><o>ἅπαξ</o>,</f> adv., <et> <e t=\"septuagint\">[in LXX for <h n=\"H259\">אֶחָד</h>, <h n=\"H6471\">פַּעַם</h>;]</e> </et> <s n=\"(a)\"><b>once</b>: <r v=\"2Cor.11.25\"></r>, <r v=\"Heb.9.26\"></r>, <r v=\"Heb.9.27\"></r>; <g>ἔτι ἅ.</g>, <r v=\"Heb.12.26\"></r>, <r v=\"Heb.12.27\"></r>; <g>ἅ. τ. ἐνιαυτοῦ</g>, <r v=\"Heb.9.7\"></r>; <g>καί ἅ. κ. δίς</g>, <b>twice</b>: <r v=\"Phil.4.16\"></r>, <r v=\"1Thess.2.18\"></r>;</s> <s n=\"(b)\"><b>once for all</b>: <r v=\"Heb.6.4\"></r> <r v=\"Heb.9.28\"></r> <r v=\"Heb.10.2\"></r>, <r v=\"1Pet.3.18\"></r>, <r v=\"Jude.1.3\"></r>, <r v=\"Jude.1.5\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G585":{"l":"ἀπόδειξις","o":1,"ar":"<f>** <o>ἀπό-δειξις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>عرض، إظهار</b>.</s> <s n=\"2.\">كما عند فلاسفة اليونان: <b>برهان</b>، <b>دليل قاطع</b>: <r v=\"1Cor.2.4\"></r>.†</s>","en":"<f>** <o>ἀπό-δειξις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποδείκνυμι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.4.20\"></r>, <r v=\"4Macc.3.19\"></r> <r v=\"4Macc.13.10\"></r>*;]</e> </et> <s n=\"1.\"><b>a showing off</b>.</s> <s n=\"2.\">As used by Gk. philosophers, <b>demonstration</b>, <b>certain proof</b>: <r v=\"1Cor.2.4\"></r> (v. <i>ICC</i>, in l.; MM, s.v.; Lft., <i>Notes</i>, 173).†</s>"},"G536":{"l":"ἀπαρχή","o":9,"ar":"<f><o>ἀπ-αρχή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>بداية الذبيحة</b> (أول ما يُقدَّم منها).</s> <s n=\"2.\"><b>باكورة</b>: <g>τοῦ φυράματος</g> (قارن <r v=\"Num.15.20\"></r>)، <r v=\"Rom.11.16\"></r>. مجازيًا، <g>ἀ. τοῦ πνεύματος</g>: <r v=\"Rom.8.23\"></r>؛ عن المسيحيين: <r v=\"Rom.16.5\"></r>، <r v=\"1Cor.16.15\"></r>، <r v=\"2Thess.2.13\"></r>، <r v=\"Jas.1.18\"></r>، <r v=\"Rev.14.4\"></r>؛ عن المسيح: <r v=\"1Cor.15.20\"></r>، <r v=\"1Cor.15.23\"></r>.†</s>","en":"<f><o>ἀπ-αρχή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπάρχομαι</g></x>, <i>to make a beginning</i> in sacrifice, <i>offer first fruits</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8641\">תְּרוּמָה</h>, <h n=\"H7225\">רֵאשִׁית</h>;]</e> </et> <s n=\"1.\"><b>the beginning of a sacrifice</b>.</s> <s n=\"2.\"><b>first fruits</b>: <g>τοῦ φυράματος</g> (cf. <r v=\"Num.15.20\"></r>), <r v=\"Rom.11.16\"></r>. Metaph., <g>ἀ. τοῦ πνεύματος</g>: <r v=\"Rom.8.23\"></r>; of Christians: <r v=\"Rom.16.5\"></r>, <r v=\"1Cor.16.15\"></r>, <r v=\"2Thess.2.13\"></r> (WH, mg., R, mg., txt., <g>ἀπ᾽ ἀρχῆς</g>; v. Lft., <i>Notes</i>, 119 f.), <r v=\"Jas.1.18\"></r>, <r v=\"Rev.14.4\"></r>; of Christ: <r v=\"1Cor.15.20\"></r>, <r v=\"1Cor.15.23\"></r> (Cremer, 117; MM, <i>VGT</i>, s.v.).†</s>"},"G555":{"l":"ἀπέκδυσις","o":1,"ar":"<f>*† <o>ἀπ-έκ-δυσις</o>، <g>-εως, ἡ</g></f> <s><b>نزع</b> أو <b>خلع</b>: <r v=\"Col.2.11\"></r>.†</s>","en":"<f>*† <o>ἀπ-έκ-δυσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(<x><g>ἀπεκδύω</g></x>),</e> </et> <s><b>a putting</b> or <b>stripping off</b>: <r v=\"Col.2.11\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G594":{"l":"ἀποδοχή","o":2,"ar":"<f>* <o>ἀπο-δοχή</o>، <g>-ῆς, ἡ</g></f> <s><b>قبول</b>، <b>استحسان</b>: <r v=\"1Tim.1.15\"></r>، <r v=\"1Tim.4.9\"></r>.†</s>","en":"<f>* <o>ἀπο-δοχή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποδέχομαι</g></x>),</e> </et> <s><b>acceptance</b>, <b>approbation</b> (Field, <i>Notes</i>, 203): <r v=\"1Tim.1.15\"></r> <r v=\"1Tim.4.9\"></r> (Cremer, 686; MM, s.v.).†</s>"},"G587":{"l":"ἀπόδεκτος","o":2,"ar":"<f>*† <o>ἀπό-δεκτος</o>، <g>-ον</g></f> <s><b>مقبول</b>: <r v=\"1Tim.2.3\"></r>، <r v=\"1Tim.5.4\"></r>.†</s>","en":"<f>*† <o>ἀπό-δεκτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>άποδέχομαι</g></x>),</e> </et> <s><b>acceptable</b>: <r v=\"1Tim.2.3\"></r> <r v=\"1Tim.5.4\"></r>.†</s>"},"G597":{"l":"ἀποθησαυρίζω","o":1,"ar":"<f>**† <o>ἀπο-θησαυρίζω</o>،</f> <s><b>يدّخر</b>، <b>يخزن كنزًا</b>: <r v=\"1Tim.6.19\"></r>.†</s>","en":"<f>**† <o>ἀπο-θησαυρίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.3.4\"></r>*;]</e> </et> <s><b>to treasure up</b>, <b>store away</b>: <r v=\"1Tim.6.19\"></r>.†</s>"},"G506":{"l":"ἀνυπότακτος","o":4,"ar":"<f>**† <o>ἀνυπότακτος</o>، <g>-ον</g></f> <s>عن الأشياء: <b>غير خاضع</b>: <r v=\"Heb.2.8\"></r>؛ عن الأشخاص: <b>متمرّد، غير منضبط</b>: <r v=\"1Tim.1.9\"></r>، <r v=\"Titus.1.6\"></r>، <r v=\"Titus.1.10\"></r>.†</s>","en":"<f>**† <o>ἀνυπότακτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ά-</g> neg., <x><g>ὑποτάσσω</g></x>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"1Sam.2.12\"></r> <r v=\"1Sam.10.27\"></r> (for LXX, <g>λοιμός</g>, <h n=\"H1121,H1100\">בּני בליעל</h>)*;]</e> </et> <s>of things, <b>not subject to rule</b>: <r v=\"Heb.2.8\"></r>; of persons, <b>unruly</b>: <r v=\"1Tim.1.9\"></r>, <r v=\"Titus.1.6\"></r>, <r v=\"Titus.1.10\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G583":{"l":"ἀπογράφω","o":4,"ar":"<f><o>ἀπο-γράφω</o>،</f> <s n=\"1.\"><b>نسخ</b>، <b>نقل كتابةً</b>.</s> <s n=\"2.\"><b>سجّل، قيّد في سجل</b>؛ الصيغة الوسطى، <b>اكتتب، سجّل نفسه</b>: <r v=\"Luke.2.1\"></r>، <r v=\"Luke.2.3\"></r>، <r v=\"Luke.2.5\"></r>؛ المبني للمجهول، <r v=\"Heb.12.23\"></r> (انظر المراجع تحت مدخل <x><g>ἀπογραφή</g></x>).†</s>","en":"<f><o>ἀπο-γράφω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.8.14\"></r>, <r v=\"Prov.22.20\"></r> (<h n=\"H3789\">כּתב</h>), <r v=\"1Esd.8.30\"></r>, <r v=\"3Macc.2.29\"></r> <r v=\"3Macc.4.14\"></r> <r v=\"3Macc.6.34\"></r>, <r v=\"3Macc.6.38\"></r>*;]</e> </et> <s n=\"1.\"><b>to write out</b>, <b>copy</b>.</s> <s n=\"2.\"><b>to enrol</b>; mid., <b>to enrol oneself</b>: <r v=\"Luke.2.1\"></r> (M, <i>Pr.</i>, 162; but. v. <i>ICC</i>, in l.), <r v=\"Luke.2.3\"></r>, <r v=\"Luke.2.5\"></r>; pass., <r v=\"Heb.12.23\"></r> (v. reff., s.v. <x><g>ἀπογραφή</g></x>).†</s>"},"G551":{"l":"ἀπείραστος","o":1,"ar":"<f>*† <o>ἀπείραστος</o>، <g>-ον</g></f> <s><b>غير مُجرَّب</b>، <b>لا يُمتحن</b>، <b>بلا خبرة</b>: <r v=\"Jas.1.13\"></r>.†</s>","en":"<f>*† <o>ἀπείραστος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>πειράζω</g></x>; for cl. <g>ἀπείρητος</g>, &lt; <x><g>πειράω</g></x>),</e> </et> <s><b>untempted</b>, <b>untried</b>, <b>without experience</b>: <r v=\"Jas.1.13\"></r> (v. Hort, in l.; MM, <i>VGT</i>, s.v.).†</s>"},"G593":{"l":"ἀποδοκιμάζω","o":9,"ar":"<f><o>ἀπο-δοκιμάζω</o>،</f> <s><b>رفض</b>: <r v=\"Matt.21.42\"></r><i>(السبعينية)</i>، <r v=\"Mark.8.31\"></r> <r v=\"Mark.12.10\"></r><i>(السبعينية)</i>، <r v=\"Luke.9.22\"></r> <r v=\"Luke.17.25\"></r> <r v=\"Luke.20.17\"></r><i>(السبعينية)</i>، <r v=\"Heb.12.17\"></r>، <r v=\"1Pet.2.4\"></r>، <r v=\"1Pet.2.7\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>ἀπο-δοκιμάζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.118.22\"></r>, al. (<h n=\"H3988\">מאס</h>);]</e> </et> <s><b>to reject</b>: <r v=\"Matt.21.42\"></r><i>(LXX)</i>, <r v=\"Mark.8.31\"></r> <r v=\"Mark.12.10\"></r><i>(LXX)</i>, <r v=\"Luke.9.22\"></r> <r v=\"Luke.17.25\"></r> <r v=\"Luke.20.17\"></r><i>(LXX)</i>, <r v=\"Heb.12.17\"></r>, <r v=\"1Pet.2.4\"></r>, <r v=\"1Pet.2.7\"></r><i>(LXX)</i> (Cremer, 701; MM, s.v.).†</s>"},"G592":{"l":"ἀποδιορίζω","o":1,"ar":"<f>* <o>ἀπο-δι-ορίζω</o></f> <s><b>فرز، فصل بحدود</b>، ومن ثَمّ مجازيًا: <b>أحدث انقسامات، اعتزل</b>: <r v=\"Jude.1.19\"></r>.†</s>","en":"<f>* <o>ἀπο-δι-ορίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>διορίζω</g></x>, &lt; <x><g>ἅρος</g></x>, <i>a limit</i>),</e> </et> <s><b>to mark off</b>, hence metaph. <b>to make separations</b>: <r v=\"Jude.1.19\"></r> (Cremer, 806).†</s>"},"G525":{"l":"ἀπαλλάσσω","o":3,"ar":"<f><o>ἀπ-αλλάσσω</o>،</f> <s><b>أزال</b>، <b>أطلق، أعتق</b>: <r v=\"Heb.2.15\"></r>؛ المبني للمجهول، <b>زال، فارق</b>: <r v=\"Acts.19.12\"></r>؛ بمعنى قانوني، يليه <g>ἀπό</g>، مع المضاف إليه للشخص، <b>تخلّص من</b>: <r v=\"Luke.12.58\"></r>.†</s>","en":"<f><o>ἀπ-αλλάσσω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5493\">סוּר</h> hi., etc.;]</e> </et> <s><b>to remove</b>, <b>release</b>: <r v=\"Heb.2.15\"></r>; pass., <b>to depart</b>: <r v=\"Acts.19.12\"></r>; in legal sense (MM, <i>VGT</i>, s.v.), seq. <g>ἀπό</g>, c. gen. pers., <b>to be quit of</b>: <r v=\"Luke.12.58\"></r> (Cremer, 90, 632).†</s>"},"G578":{"l":"ἀποβλέπω","o":1,"ar":"<f><o>ἀπο-βλέπω</o>،</f> <s><b>صرف نظره عن كل شيء آخر إلى شيء واحد</b>؛ ومن ثم، <b>نظر بثبات</b>: <r v=\"Heb.11.26\"></r> (قارن <x><g>ἀφοράω</g></x>).†</s>","en":"<f><o>ἀπο-βλέπω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6437\">פּנה</h>, etc.;]</e> </et> <s><b>to look away from all else at one object</b>; hence, <b>to look steadfastly</b>: <r v=\"Heb.11.26\"></r> (cf. <x><g>ἀφοράω</g></x>).†</s>"},"G541":{"l":"ἀπαύγασμα","o":1,"ar":"<f>**† <o>ἀπ-αύγασμα</o>، <g>-τος, τό</g></f> <s>عن النور المنبعث من جسم مضيء، <b>بهاء</b>، <b>إشراق</b>: <r v=\"Heb.1.3\"></r>.†</s>","en":"<f>**† <o>ἀπ-αύγασμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>αὐγή</g></x>, <i>brightness</i>, whence <x><g>ἀπαυγάζω</g></x>, <i>to radiate</i> or <i>reflect</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.7.26\"></r>*;]</e> </et> <s>of light beaming from a luminous body, <b>radiance</b>, <b>effulgence</b>: <r v=\"Heb.1.3\"></r>.†</s>"},"G574":{"l":"ἁπλῶς","o":1,"ar":"<f><o>ἁπλῶς</o>،</f> ظرف <s><b>ببساطة</b>، <b>بإخلاص</b>، <b>بسخاء</b>: <r v=\"Jas.1.5\"></r>. (قارن <r v=\"Jas.1.5\"></r>)†</s>","en":"<f><o>ἁπλῶς</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <x><g>ἁπλοῦς</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.10.9\"></r> (<h n=\"H8537\">בַּתֹּם</h>), <r v=\"Wis.16.27\"></r>, <r v=\"2Macc.6.6\"></r>*;]</e> </et> <s><b>simply</b>, <b>sincerely</b>, <b>graciously</b>: <r v=\"Jas.1.5\"></r>. (\"Later writers comprehend under the one word the whole magnanimous and honourable type of character in which ... singleness of mind is the central feature\"—Hort, <r v=\"Jas.1.5\"></r>)†</s>"},"G586":{"l":"ἀποδεκατεύω","o":4,"ar":"<f>*† <o>ἀπο-δεκατεύω</o> = <x><g>ἀποδεκατόω</g></x>، انظره،</f> <s><b>عشّر</b>، <b>أدّى العُشر من</b>: <r v=\"Luke.18.12\"></r>.†</s>","en":"<f>*† <o>ἀπο-δεκατεύω</o> = <x><g>ἀποδεκατόω</g></x>, q.v.,</f> <s><b>to tithe</b>, <b>pay a tenth of</b>: <r v=\"Luke.18.12\"></r>.†</s>"},"G577":{"l":"ἀποβάλλω","o":3,"ar":"<f><o>ἀπο-βάλλω</o>،</f> <s><b>طرح عنه</b>: <r v=\"Mark.10.50\"></r>؛ مجازيًا: <b>فقد</b>، <b>ترك</b>: <r v=\"Heb.10.35\"></r>.†</s>","en":"<f><o>ἀπο-βάλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.1.30\"></r> (<h n=\"H5034\">נבל</h>) and elsew. without <i>Heb.</i> equiv.;]</e> </et> <s><b>to throw off</b>: <r v=\"Mark.10.50\"></r>; metaph., <b>to lose</b>, <b>let go</b> (Field, <i>Notes</i>, 231 f.; MM, s.v.): <r v=\"Heb.10.35\"></r>.†</s>"},"G595":{"l":"ἀπόθεσις","o":2,"ar":"<f>* <o>ἀπό-θεσις</o>، <g>-εως, ἡ</g></f> <s><b>خلع، نزع</b>: <r v=\"1Pet.3.21\"></r>، <r v=\"2Pet.1.14\"></r>.†</s>","en":"<f>* <o>ἀπό-θεσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποτίθημι</g></x>),</e> </et> <s><b>a putting away</b>: <r v=\"1Pet.3.21\"></r>, <r v=\"2Pet.1.14\"></r>.†</s>"},"G500":{"l":"ἀντίχριστος","o":5,"ar":"<f>*† <o>ἀντί-χριστος</o>، <g>-ον, ὁ</g>،</f> <s><b>ضد المسيح</b>، «من يتّخذ مظهر المسيح ويقاوم المسيح»: <r v=\"1John.2.18\"></r>، <r v=\"1John.2.22\"></r>، <r v=\"1John.4.3\"></r>، <r v=\"2John.1.7\"></r>؛ في الجمع <r v=\"1John.2.18\"></r> (قارن <x><g>ψευδόχριστος</g></x>).†</s>","en":"<f>*† <o>ἀντί-χριστος</o>, <g>-ον, ὁ</g>,</f> <s>Antichrist, \"one who assuming the guise of Christ opposes Christ\" (Westc., <i>Epp. Jo.</i>, 70): <r v=\"1John.2.18\"></r>, <r v=\"1John.2.22\"></r> <r v=\"1John.4.3\"></r>, <r v=\"2John.1.7\"></r> pl. <r v=\"1John.2.18\"></r> (cf. <x><g>ψευδόχριστος</g></x>, and v. MM, <i>VGT</i>, s.v.).†</s>"},"G552":{"l":"ἄπειρος","o":1,"ar":"<f><o>ἄπειρος</o>، <g>-ον</g></f> <s><b>عديم الخبرة بـ</b>: مع مضاف إليه الشيء، <r v=\"Heb.5.13\"></r>.†</s>","en":"<f><o>ἄπειρος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>πεῖρα</g></x>, <i>trial</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.14.23\"></r>, <r v=\"Zech.11.15\"></r> (<h n=\"H196\">אֱוִילִי</h>), <r v=\"Jer.2.6\"></r> (<h n=\"H6160\">עֲרָבָה</h>)*;]</e> </et> <s><b>without experience of</b>: c. gen. rei, <r v=\"Heb.5.13\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G581":{"l":"ἀπογίνομαι","o":null,"ar":"<f>** <o>ἀπο-γίνομαι</o></f> <s n=\"1.\"><b>يكون بعيدًا</b>، <b>منفصلاً عن</b>.</s> <s n=\"2.\"><b>يفارق الحياة</b>، <b>يموت</b>: <g>τ. ἁμαρτίαις</g>، أي من جهة الخطايا، <r v=\"1Pet.2.24\"></r>.†</s>","en":"<f>** <o>ἀπο-γίνομαι</o> (cl. <g>-γίγν-</g>)</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.2.1\"></r>*;]</e> </et> <s n=\"1.\"><b>to be away</b>, <b>removed from</b>.</s> <s n=\"2.\"><b>to depart life</b>, <b>to die</b> (MM, s.v.): <g>τ. ἁμαρτίαις</g>, i.e. with ref. to sins, <r v=\"1Pet.2.24\"></r> (Cremer, 149, 668).†</s>"},"G504":{"l":"ἄνυδρος","o":4,"ar":"<f><o>ἄνυδρος</o>، <g>-ον</g></f> <s><b>بلا ماء، يابس</b>: <g>τόποι</g>، <r v=\"Matt.12.43\"></r>، <r v=\"Luke.11.24\"></r>؛ <g>πηγαί</g>، <r v=\"2Pet.2.17\"></r>؛ <g>νεφέλαι</g>، <r v=\"Jude.1.12\"></r>.†</s>","en":"<f><o>ἄνυδρος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>ὕδωρ</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6723\">צִיָּה</h>, <h n=\"H3452\">יְשִׁימוֹן</h> (<g>γῆ ἄ</g>), etc.;]</e> </et> <s><b>waterless</b>: <g>τόποι</g>, <r v=\"Matt.12.43\"></r>, <r v=\"Luke.11.24\"></r>; <g>πηγαί</g>, <r v=\"2Pet.2.17\"></r>; <g>νεφέλαι</g>, <r v=\"Jude.1.12\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G534":{"l":"ἀπάρτι","o":1,"ar":"<f>* <o>ἀπάρτι</o> (<g>ἀπ᾽ ἄρτι</g>)؛</f> ظرف، <s><b>من الآن</b>، <b>من الآن فصاعدًا</b>: <r v=\"John.13.19\"></r> <r v=\"John.14.7\"></r>، <r v=\"Rev.14.13\"></r>.†</s>","en":"<f>* <o>ἀπάρτι</o> (WH, <g>ἀπ᾽ ἄρτι</g>; cl., <g>ἀπαρτί</g>, v. MM, <i>VGT</i>, s.v.);</f> adv., <et> <e t=\"septuagint\">[not in LXX, where <h n=\"H6258\">מֵעַתָּה</h> is rendered by <g>ἀπὸ τοῦ νῦν</g>;]</e> </et> <s><b>from now</b>, <b>henceforth</b>: <r v=\"John.13.19\"></r> <r v=\"John.14.7\"></r>, <r v=\"Rev.14.13\"></r>.†</s>"},"G540":{"l":"ἀπάτωρ","o":1,"ar":"<f>* <o>ἀπάτωρ</o>، <g>-ορος, ὁ, ὴ</g></f> <s n=\"1.\"><b>يتيم الأب</b>.</s> <s n=\"2.\"><b>بلا أب</b>، أي بلا نسب مدوَّن: <r v=\"Heb.7.3\"></r>.†</s>","en":"<f>* <o>ἀπάτωρ</o>, <g>-ορος, ὁ, ὴ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>πατήρ</g></x>);</e> </et> <s n=\"1.\"><b>fatherless</b>.</s> <s n=\"2.\"><b>without father</b> (MM, <i>VGT</i>, s.v.), i.e., with no recorded genealogy: <r v=\"Heb.7.3\"></r>.†</s>"},"G546":{"l":"ἀπειλέω","o":2,"ar":"<f><o>ἀπειλέω</o>، <g>-ῶ</g></f> <s><b>يهدِّد</b>: <r v=\"1Pet.2.23\"></r>؛ الصيغة الوسطى، <r v=\"Acts.4.17\"></r> (قارن <x><g>προσαπειλέω</g></x>).†</s>","en":"<f><o>ἀπειλέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(<x><g>ἀπειλή</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Nah.1.4\"></r> (<h n=\"H1605\">גּער</h>), <r v=\"Isa.66.14\"></r> (<h n=\"H2194\">זעם</h>), <r v=\"Sir.19.17\"></r>, al.;]</e> </et> <s><b>to threaten</b>: <r v=\"1Pet.2.23\"></r>; mid., <r v=\"Acts.4.17\"></r> (v. MM, <i>VGT</i>, s.v., and cf. <x><g>προσαπειλέω</g></x>).†</s>"},"G531":{"l":"ἀπαράβατος","o":1,"ar":"<f>*† <o>ἀ-παρά-βατος</o>، <g>-ον</g></f> <s><b>لا يُنتهَك</b>، ومن ثمّ <b>لا يزول، لا يتغيّر</b>: <r v=\"Heb.7.24\"></r>.†</s>","en":"<f>*† <o>ἀ-παρά-βατος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>παραβαίνω</g></x>),</e> </et> <s><b>inviolable</b>, and so unchangeable: <r v=\"Heb.7.24\"></r> (v. Westc., in l.; Cremer, 653; MM, <i>VGT</i>, s.v.).†</s>"},"G560":{"l":"ἀπελπίζω","o":1,"ar":"<f>† <o>ἀπ-ελπίζω</o>،</f> <s n=\"1.\">عند الكتّاب المتأخرين وفي السبعينية: <b>يئس</b>، <b>قطع الرجاء من</b>.</s> <s n=\"2.\"><b>رجا أن ينال من</b> أو <b>في المقابل</b>: مع المنصوب، <r v=\"Luke.6.35\"></r>.†</s>","en":"<f>† <o>ἀπ-ελπίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.29.19\"></r> (<h n=\"H34\">אֶבְיוֹן</h>), <r v=\"Jdt.9.11\"></r>, <r v=\"Ezra.4.17\"></r>, <r v=\"Sir.22.21\"></r> <r v=\"Sir.27.21\"></r>, <r v=\"2Macc.9.18\"></r>*;]</e> </et> <s n=\"1.\"><b>to give up in despair</b>, <b>despair of</b> (Polyb., Diod., LXX).</s> <s n=\"2.\"><b>to hope to receive from</b> or <b>in return</b> (Field, <i>Notes</i>, 59; Cremer, 712; Soph., <i>Lex.</i>, s.v.): c. acc. (M; <i>Pr.</i>, 65; MM, s.v.), <r v=\"Luke.6.35\"></r>.†</s>"},"G590":{"l":"ἀπόδημος","o":1,"ar":"<f>* <o>ἀπό-δημος</o>، <g>-ον</g>،</f> <s><b>مسافر إلى بلد بعيد</b> (الترجمة المنقحة: <i>مُقيم في بلد آخر</i>): <r v=\"Mark.13.34\"></r>.†</s>","en":"<f>* <o>ἀπό-δημος</o>, <g>-ον</g>,</f> <s><b>gone abroad</b> (RV, <i>sojourning in another country</i>): <r v=\"Mark.13.34\"></r>.†</s>"},"G556":{"l":"ἀπελαύνω","o":1,"ar":"<f><o>ἀπ-ελαύνω</o>،</f> <s><b>طرد</b>: <r v=\"Acts.18.16\"></r>.†</s>","en":"<f><o>ἀπ-ελαύνω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5337\">נצל</h>, <h n=\"H7971\">שׁלח</h>;]</e> </et> <s><b>to drive away</b>: <r v=\"Acts.18.16\"></r> (MM, s.v.).†</s>"},"G510":{"l":"ἀνωτερικός","o":1,"ar":"<f>* <o>ἀνωτερικός</o>، <g>-ή, όν</g></f> <s><b>عالٍ، علوي</b>: <r v=\"Acts.19.1\"></r>.†</s>","en":"<f>* <o>ἀνωτερικός</o>, <g>-ή, όν</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνώτερος</g></x>),</e> </et> <s><b>upper</b>: <r v=\"Acts.19.1\"></r>.†</s>"},"G502":{"l":"ἄντλημα","o":1,"ar":"<f>*† <o>ἄντλημα</o>، <g>-τος, τό</g></f> <s n=\"(a)\">أصلاً: <b>ما يُستقى</b>؛</s> <s n=\"(b)\"><b>ما يُستقى به</b>، <b>دلو</b>: <r v=\"John.4.11\"></r>.†</s>","en":"<f>*† <o>ἄντλημα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀντλέω</g></x>),</e> </et> <s n=\"(a)\">prop., <b>what is drawn</b> (Diosc.);</s> <s n=\"(b)\"><b>a vessel to draw with</b>, <b>a bucket</b> (Plut.; v. Abbott, <i>Essays</i>, 88): <r v=\"John.4.11\"></r>.†</s>"},"G522":{"l":"ἀπαίρω","o":22,"ar":"<f><o>ἀπ-αίρω</o>،</f> <s><b>رفع عن</b>، ومن ثم <b>أخذ، رفع</b>؛ المبني للمجهول: <r v=\"Matt.9.15\"></r>، <r v=\"Mark.2.20\"></r>، <r v=\"Luke.5.35\"></r>.†</s>","en":"<f><o>ἀπ-αίρω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5265\">נסע</h>;]</e> </et> <s><b>to lift off</b>, hence, <b>to take away</b>; pass.: <r v=\"Matt.9.15\"></r>, <r v=\"Mark.2.20\"></r>, <r v=\"Luke.5.35\"></r>.†</s>"},"G527":{"l":"ἀπαλός","o":2,"ar":"<f><o>ἀπαλός</o>، <g>-ή, -όν</g>،</f> <s><b>رَخْص، غضّ</b>: <r v=\"Matt.24.32\"></r>، <r v=\"Mark.13.28\"></r>.†</s>","en":"<f><o>ἀπαλός</o>, <g>-ή, -όν</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7390\">רַךְ</h>;]</e> </et> <s><b>tender</b>: <r v=\"Matt.24.32\"></r>, <r v=\"Mark.13.28\"></r>.†</s>"},"G564":{"l":"ἀπερίτμητος","o":1,"ar":"<f>† <o>ἀ-περί-τμητος</o>، <g>-ον</g></f> <s><b>أغلف</b>؛ مجازيًا (<g>τ.</g>) <g>καρδίαις</g> (قارن <r v=\"Jer.9.26\"></r>، وفي مواضع أخرى): <r v=\"Acts.7.51\"></r>.†</s>","en":"<f>† <o>ἀ-περί-τμητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>περιτέμνω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6189\">עָרֵל</h>;]</e> </et> <s><b>uncircumcised</b>; metaph. (<g>τ.</g>) <g>καρδίαις</g> (cf. <r v=\"Jer.9.26\"></r>, al.): <r v=\"Acts.7.51\"></r>. (<g>ἄσημος</g>, found in <g>π.</g>, appears to have been the word used by Greek-speaking Egyptians: v. Deiss., <i>BS</i>, 153; cf. also Cremer, 885; MM, s.v.)†</s>"},"G549":{"l":"ἄπειμι_2","o":8,"ar":"<f>* <o>ἄπ-ειμι</o></f> <s><b>يمضي، ينصرف</b>: <r v=\"Acts.17.10\"></r>.†</s>","en":"<f>* <o>ἄπ-ειμι</o></f> <et> <e t=\"derivation\">(<x><g>εἶμι</g></x>, <l>ibo</l>),</e> </et> <s><b>to depart</b>: <r v=\"Acts.17.10\"></r>.†</s>"},"G503":{"l":"ἀντοφθαλμέω","o":1,"ar":"<f>**† <o>ἀντοφθαλμέω</o>، <g>-ῶ</g></f> <s>عند الكتّاب المتأخرين: <b>نظر في الوجه</b>، <b>حدّق مباشرة</b>. ومجازيًا: <b>واجه</b>، <b>قاوم</b> (<r v=\"Wis.12.14\"></r>): مع القابل، <g>ἀ. τ. ἀνέμῳ</g>، كمصطلح بحري: <b>أقلع ضد الريح</b>: <r v=\"Acts.27.15\"></r>.†</s>","en":"<f>**† <o>ἀντοφθαλμέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ὀφθαλμός</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.12.14\"></r>*;]</e> </et> <s><b>to look in the face</b>, <b>look straight at</b> (Polyb.). Metaph., <b>to face</b>, <b>withstand</b> (<r v=\"Wis.12.14\"></r>, Polyb.): c. dat., <g>ἀ. τ. ἀνέμῳ</g>, as nautical term, <b>to beat up against the wind</b> (v. <i>DB</i>, <i>ext.</i>, 366 f.; MM, <i>VGT</i>, s.v.): <r v=\"Acts.27.15\"></r>.†</s>"},"G589":{"l":"ἀποδημέω","o":6,"ar":"<f><o>ἀπο-δημέω</o>، <g>-ῶ</g></f> <s><b>كان</b> أو <b>سافر</b> إلى بلد بعيد: <r v=\"Matt.21.33\"></r> <r v=\"Matt.25.14\"></r>، <r v=\"Matt.25.15\"></r>، <r v=\"Mark.12.1\"></r>، <r v=\"Luke.15.13\"></r> <r v=\"Luke.20.9\"></r>.†</s>","en":"<f><o>ἀπο-δημέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπόδημος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.19.3\"></r> A*;]</e> </et> <s><b>to be</b> or <b>go abroad</b> (M, <i>Pr.</i>, 130<i>2</i>): <r v=\"Matt.21.33\"></r> <r v=\"Matt.25.14\"></r>, <r v=\"Matt.25.15\"></r>, <r v=\"Mark.12.1\"></r>, <r v=\"Luke.15.13\"></r> <r v=\"Luke.20.9\"></r>.†</s>"},"G533":{"l":"ἀπαρνέομαι","o":11,"ar":"<f><o>ἀπ-αρνέομαι</o> (<g>-οῦμαι</g>) فعل لازم الصيغة الوسطى،</f> <s><b>أنكر</b>، أي رفض الاعتراف بـ، تجاهل: مع المنصوب، عن إنكار المرء نفسه، <r v=\"Matt.16.24\"></r>، <r v=\"Mark.8.34\"></r>، <r v=\"Luke.9.23\"></r>؛ عن إنكار بطرس للمسيح، <r v=\"Matt.26.34\"></r>، <r v=\"Matt.26.35\"></r>، <r v=\"Matt.26.75\"></r>، <r v=\"Mark.14.30\"></r>، <r v=\"Mark.14.31\"></r>، <r v=\"Mark.14.72\"></r>، <r v=\"Luke.22.34\"></r>، <r v=\"Luke.22.61\"></r>؛ المبني للمجهول، <r v=\"Luke.12.9\"></r>.†</s>","en":"<f><o>ἀπ-αρνέομαι</o> (<g>-οῦμαι</g>) depon.,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.31.7\"></r> (<h n=\"H3988\">מאס</h>)*;]</e> </et> <s><b>to deny</b>, i.e. to refuse to recognize, to ignore: c. acc., of oneself (<i>DCG</i>, ii, 598 f.), <r v=\"Matt.16.24\"></r>, <r v=\"Mark.8.34\"></r> (MM, <i>VGT</i>, s.v.), <r v=\"Luke.9.23\"></r> (WH, mg., txt., <g>ἀρν-</g>) of Peter's denials of Christ, <r v=\"Matt.26.34\"></r>, <r v=\"Matt.26.35\"></r>, <r v=\"Matt.26.75\"></r>, <r v=\"Mark.14.30\"></r>, <r v=\"Mark.14.31\"></r>, <r v=\"Mark.14.72\"></r>, <r v=\"Luke.22.34\"></r>, <r v=\"Luke.22.61\"></r>; pass., <r v=\"Luke.12.9\"></r> (Cremer, 111).†</s>"},"G501":{"l":"ἀντλέω","o":4,"ar":"<f><o>ἀντλέω</o>، <g>-ῶ</g></f> <s n=\"1.\">أصلاً: <b>نزح</b> الماء.</s> <s n=\"2.\">عمومًا: <b>استقى ماءً</b>: مطلقًا، <r v=\"John.2.8\"></r>، <r v=\"John.4.15\"></r>؛ <g>ὕδωρ</g>، <r v=\"John.2.9\"></r>، <r v=\"John.4.7\"></r>.†</s>","en":"<f><o>ἀντλέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄντλος</g></x>, <i>bilge-water in a hold</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7579\">שׁאב</h>, etc.;]</e> </et> <s n=\"1.\">prop., <b>to bale out</b>.</s> <s n=\"2.\">Generally, <b>to draw water</b>: absol., <r v=\"John.2.8\"></r> <r v=\"John.4.15\"></r>; <g>ὕδωρ</g>, <r v=\"John.2.9\"></r> <r v=\"John.4.7\"></r> (on its use of the water made wine, v. <i>DCG</i>, ii, 815<i>a</i>; MM, <i>VGT</i>, s.v.; Field, <i>Notes</i>, 84 f.).†</s>"},"G573":{"l":"ἁπλοῦς","o":2,"ar":"<f><o>ἁπλοῦς</o>، <g>-ῆ, -οῦν</g></f> <s><b>بسيط</b>، <b>مفرد، سليم</b>: بالمعنى الأخلاقي، <g>ἀφθαλμός</g>، <r v=\"Matt.6.22\"></r>، <r v=\"Luke.11.34\"></r>.†</s>","en":"<f><o>ἁπλοῦς</o>, <g>-ῆ, -οῦν</g></f> <et> <e t=\"derivation\">(contr. fr. <g>-όος</g>; &lt; <g>ἁ.-</g> cop., <g>πλόος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.11.25\"></r>*;]</e> </et> <s><b>simple</b>, <b>single</b>: in a moral sense (<i>DCG</i>, ii, 628 f.), <g>ἀφθαλμός</g>, <r v=\"Matt.6.22\"></r>, <r v=\"Luke.11.34\"></r>. (In <g>π.</g> of a marriage dowry, v. MM, s.v.).†</s> <sy><i>SYN.</i>: <x><g>ἄδολος</g></x>, <x><g>ἄκακος</g></x>, <x><g>ἀκέραιος</g></x> (Tr., <i>Syn.</i>, § lvi; Cremer, 107, 639).</sy>"},"G508":{"l":"ἀνάγαιον","o":null,"ar":"<f>* <o>ἀνάγαιον</o>، <g>-ου, τό</g></f> <s><b>علّية</b>: <r v=\"Mark.14.15\"></r>، <r v=\"Luke.22.12\"></r>.†</s>","en":"<f>* <o>ἀνάγαιον</o> (Rec. <g>ἀνώγεον</g>; on the form, v. Rutherford, <i>NPhr.</i>, 357 f.; MM, <i>VGT</i>, s.v.), <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνά</g></x>, <x><g>γῆ</g></x>),</e> </et> <s><b>an upper room</b>: <r v=\"Mark.14.15\"></r>, <r v=\"Luke.22.12\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ὑπερῷον</g></x>.</sy>"},"G535":{"l":"ἀπαρτισμός","o":1,"ar":"<f>*† <o>ἀπαρτισμός</o>، <g>-οῦ, ὁ</g></f> <s><b>إكمال، إتمام</b>: <r v=\"Luke.14.28\"></r>.†</s>","en":"<f>*† <o>ἀπαρτισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπαρτίζω</g></x>, <i>to finish</i>),</e> </et> <s><b>completion</b>: <r v=\"Luke.14.28\"></r> (cf. MM, <i>VGT</i>, s.v.).†</s>"},"G596":{"l":"ἀποθήκη","o":6,"ar":"<f><o>ἀπο-θήκη</o>، <g>-ης, ἡ</g></f> <s><b>مخزن</b>، <b>مخزن غلال (هُري)</b>: <r v=\"Matt.3.12\"></r> <r v=\"Matt.6.26\"></r> <r v=\"Matt.13.30\"></r>، <r v=\"Luke.3.17\"></r> <r v=\"Luke.12.18\"></r>، <r v=\"Luke.12.24\"></r>.†</s>","en":"<f><o>ἀπο-θήκη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποτίθημι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H214\">אוֹצָר</h>, <h n=\"H2935\">טֶנֶא</h>, etc.;]</e> </et> <s><b>a storehouse</b>, <b>granary</b>: <r v=\"Matt.3.12\"></r> <r v=\"Matt.6.26\"></r> <r v=\"Matt.13.30\"></r>, <r v=\"Luke.3.17\"></r> <r v=\"Luke.12.18\"></r>, <r v=\"Luke.12.24\"></r>.†</s>"},"G519":{"l":"ἀπάγχω","o":1,"ar":"<f><o>ἀπ-άγχω</o></f> <s><b>خنق</b>؛ الصيغة الوسطى، <b>خنق نفسه (شنق نفسه)</b> (أو <i>اختنق</i>): <r v=\"Matt.27.5\"></r>.†</s>","en":"<f><o>ἀπ-άγχω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄγχω</g></x>, <i>to press</i>, <i>strangle</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.17.23\"></r> (<h n=\"H2614\">חנק</h>), <r v=\"Tob.3.10\"></r>*;]</e> </et> <s><b>to strangle</b>; mid., <b>to hang oneself</b> (or, <i>to choke</i>; v. M, <i>Pr.</i>, 155): <r v=\"Matt.27.5\"></r>.†</s>"},"G528":{"l":"ἀπαντάω","o":7,"ar":"<f><o>ἀπαντάω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>خرج للقاء</b>.</s> <s n=\"2.\"><b>لاقى، قابل</b>؛ مع القابل: <r v=\"Mark.14.13\"></r>، <r v=\"Luke.17.12\"></r>.†</s>","en":"<f><o>ἀπαντάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6293\">פּגע</h>;]</e> </et> <s n=\"1.\"><b>to go to meet</b>.</s> <s n=\"2.\"><b>to meet</b>; c. dat.: <r v=\"Mark.14.13\"></r>, <r v=\"Luke.17.12\"></r> (WH, mg., <g>ὑπ-</g>; in Rec. freq. as v.1. for <g>ὑπ-</g>, q.v.).†</s>"},"G513":{"l":"ἀξίνη","o":2,"ar":"<f><o>ἀξίνη</o>، <g>-ης, ἡ</g>،</f> <s><b>فأس</b>: <r v=\"Matt.3.10\"></r>، <r v=\"Luke.3.9\"></r>.†</s>","en":"<f><o>ἀξίνη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1631\">גַּרְזֶן</h>, <h n=\"H7134\">קַרְדֹּם</h>;]</e> </et> <s><b>an axe</b>: <r v=\"Matt.3.10\"></r>, <r v=\"Luke.3.9\"></r>.†</s>"},"G523":{"l":"ἀπαιτέω","o":4,"ar":"<f><o>ἀπ-αιτέω</o>، <g>-ῶ</g>،</f> <s><b>طلب ردّ الشيء</b>، <b>استردّ</b>: <r v=\"Luke.6.30\"></r> <r v=\"Luke.12.20\"></r>.†</s>","en":"<f><o>ἀπ-αιτέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.15.2\"></r>, <r v=\"Deut.15.3\"></r>, al. (<h n=\"H5065\">נגשׂ</h>), <r v=\"Sir.20.15\"></r>, <r v=\"Wis.15.8\"></r>, al.;]</e> </et> <s><b>to ask back</b>, <b>demand back</b>: <r v=\"Luke.6.30\"></r> <r v=\"Luke.12.20\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G582":{"l":"ἀπογραφή","o":2,"ar":"<f><o>ἀπο-γραφή</o>، <g>-ῆς, ἡ</g> (<g>ἀπογράφω</g>)،</f> <s n=\"1.\"><b>نسخة مكتوبة</b>.</s> <s n=\"2.\">في اليونانية الكلاسيكية: كمصطلح قانوني، <b>إفادة مكتوبة</b>.</s> <s n=\"3.\">عند الكتّاب المتأخرين: <b>سجلّ</b>، <b>اكتتاب</b>، <b>إحصاء</b>: <r v=\"Luke.2.2\"></r>، <r v=\"Acts.5.37\"></r>.†</s>","en":"<f><o>ἀπο-γραφή</o>, <g>-ῆς, ἡ</g> (<g>ἀπογράφω</g>),</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.10.21\"></r> (<h n=\"H3791\">כְּתָב</h>), <r v=\"1Esd.8.30\"></r>, AB, <r v=\"2Macc.2.1\"></r>, <r v=\"3Macc.2.32\"></r> <r v=\"3Macc.4.15\"></r>, <r v=\"3Macc.4.17\"></r> <r v=\"3Macc.7.22\"></r>*;]</e> </et> <s n=\"1.\"><b>a written copy</b>.</s> <s n=\"2.\">As law term, <b>a deposition</b> (Demos.).</s> <s n=\"3.\">In late writers, <b>a register</b>, <b>enrolment</b>, <b>census</b> (MM, s.v.; Deiss., <i>LAE</i>, 160, 268 f.): <r v=\"Luke.2.2\"></r>, <r v=\"Acts.5.37\"></r>.†</s>"},"G588":{"l":"ἀποδέχομαι","o":11,"ar":"<f>** <o>ἀπο-δέχομαι </o></f> <s><b>قبل بفرح</b>، <b>رحّب</b>، <b>استقبل</b>: <r v=\"Luke.8.40\"></r>، <r v=\"Luke.9.11\"></r>، <r v=\"Acts.18.27\"></r>، <r v=\"Acts.21.17\"></r>، <r v=\"Acts.28.30\"></r>؛ مجازيًا، مع منصوب الشيء، <r v=\"Acts.2.41\"></r>، <r v=\"Acts.24.3\"></r>.†</s>","en":"<f>** <o>ἀπο-δέχομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Tob.7.17\"></r>, <r v=\"Jdt.13.13\"></r>; <r v=\"Jdt.13.1\"></r>, I-IV Mac<i>10</i>*;]</e> </et> <s><b>to accept gladly</b>, <b>welcome</b>, <b>receive</b>: <r v=\"Luke.8.40\"></r> <r v=\"Luke.9.11\"></r>, <r v=\"Acts.18.27\"></r> <r v=\"Acts.21.17\"></r> <r v=\"Acts.28.30\"></r>; metaph., c. acc. rei, <r v=\"Acts.2.41\"></r> <r v=\"Acts.24.3\"></r> (MM, s.v.; Cremer, 688).†</s>"},"G511":{"l":"ἀνώτερος","o":1,"ar":"<f><o>ἀνώτερος</o>، <g>α, -ον</g>،</f> <s n=\"(a)\">عن الحركة، <b>إلى أعلى</b>: <r v=\"Luke.14.10\"></r>؛</s> <s n=\"(b)\">عن السكون، <b>فوق</b>، <b>سابقًا (أعلاه)</b>: <r v=\"Heb.10.8\"></r>.†</s>","en":"<f><o>ἀνώτερος</o>, <g>α, -ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Neh.3.25\"></r> (<h n=\"H5945\">עֶלְיוֹן</h>), <r v=\"Ezek.41.7\"></r> (<h n=\"H4604\">מַעַל</h>), <r v=\"Tob.8.3\"></r>*;]</e> <e t=\"derivation\">only in neut., as adv. (cf. <x><g>ἐξώτερος</g></x>),</e> </et> <s n=\"(a)\">of motion, <b>higher</b>: <r v=\"Luke.14.10\"></r>;</s> <s n=\"(b)\">of rest, <b>above</b>, <b>before</b>: <r v=\"Heb.10.8\"></r>.†</s>"},"G598":{"l":"ἀποθλίβω","o":1,"ar":"<f><o>ἀπο-θλίβω</o>،</f> <s><b>ضغط بشدّة، زحم</b>: <r v=\"Luke.8.45\"></r>.†</s>","en":"<f><o>ἀπο-θλίβω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3905\">לחץ</h>, <r v=\"Num.22.25\"></r>*;]</e> </et> <s><b>to press hard</b>: <r v=\"Luke.8.45\"></r>.†</s>"}});A.got[5]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});